window.ISSUES=[{"id":"2026-11-05-1","date":"2026-11-05","tag":"실손보험","title":"실손 부지급률이 1.13%에서 0.95%로 내렸는데, 5세대 효과라고 보긴 어려워요","thread":{"id":"silson-reform","name":"실손보험 개편"},"companies":["메리츠화재","한화손해보험","롯데손해보험","흥국화재","삼성화재","현대해상","KB손해보험","DB손해보험","NH농협손해보험"],"jobs":["상품개발","보상·손해사정"],"summary":"실손 부지급률이 1.13%에서 0.95%로 내렸는데, 5세대는 5월에야 나와서 그 덕이라고 보긴 어렵대.","co":["삼성화재","DB손해보험","현대해상","KB손해보험","메리츠화재","한화손해보험","롯데손해보험","흥국화재","NH농협손해보험"],"p0":"손해보험사 11곳의 **부지급률은 1.13%에서 0.95%로** 내렸고, 청구 건수는 3.6% 줄었는데 보험금 지급액은 2.2% 늘었어요.","hi":1,"tn":["부지급률","실손보험","비급여","자기부담률"]},{"id":"2026-11-05-2","date":"2026-11-05","tag":"정보보호","title":"해킹이 금융 37개사로 번지자, 금융위가 580여 곳을 전수 점검해요","thread":{"id":"insurer-security","name":"보험사 해킹과 정보보호"},"jobs":["리스크관리"],"summary":"해킹이 금융 37개사로 번지니까 금융위가 580곳을 싹 점검하고, 또 뚫리면 사장 책임을 묻겠대.","p0":"금융위는 약 **580개사의 외부접점과 내부통제**를 점검하고, 고객 피해와 직결된 취약점이 나오면 해당 서비스를 즉시 중단하도록 했어요.","hi":1,"tn":["망분리","내부통제","운영위험","현장점검"]},{"id":"2026-11-05-3","date":"2026-11-05","tag":"판매채널","title":"GA 10월 실적이 6월보다 23.9% 줄었는데, 감소분의 97%가 생보에서 나왔어요","thread":{"id":"sales-channel","name":"판매채널과 수수료"},"companies":["삼성생명","교보생명"],"jobs":["영업·채널","상품개발"],"summary":"GA 10월 실적이 6월보다 24% 가까이 줄었고 그 줄어든 몫의 대부분이 생보야. 손보 비중이 는 건 손보가 큰 게 아니라 생보가 빠진 거래.","co":["삼성생명","교보생명"],"p0":"7월 **1200% 룰**이 GA에도 적용된 뒤 실적은 6월 1,044억 원에서 7월 926억 원으로 떨어졌고, 9월 957억 원으로 반등했다가 10월 795억 원이 됐어요.","hi":1,"tn":["1200% 룰","분급","법인보험대리점","기저효과"]},{"id":"2026-11-05-4","date":"2026-11-05","tag":"인수합병","title":"손보사 투자한도 소진율 21.2%, 메리츠화재는 66.6%인데 삼성화재는 9.1%예요","thread":{"id":"insurer-mna","name":"보험사 인수합병과 사업 확장"},"companies":["삼성화재","현대해상","KB손해보험","DB손해보험","메리츠화재","하나손해보험","한화손해보험","코리안리","한화생명","흥국생명"],"jobs":["리스크관리"],"summary":"손보사들이 자회사에 투자할 수 있는 한도를 평균 21%쯤 썼는데, 메리츠화재는 67%, 삼성화재는 9%라서 회사마다 천차만별이야.","co":["한화생명","흥국생명","삼성화재","DB손해보험","현대해상","KB손해보험","메리츠화재","한화손해보험","하나손해보험","코리안리"],"p0":"보험사가 대주주나 자회사의 채권·주식을 들고 있을 수 있는 **투자한도는 자기자본의 60%와 총자산의 3% 중 적은 금액**이에요.","hi":1,"tn":["투자한도","지급여력비율","투자손익"]},{"id":"2026-11-04-1","date":"2026-11-04","tag":"감독·계리","title":"올해 결산부터 '계리가정 근거'를 보고서로, 보험업감독규정이 바뀌었다","thread":{"id":"actuarial-supervision","name":"계리감독 강화"},"jobs":["계리","리스크관리"],"summary":"보험사가 보험료랑 부채 계산할 때 쓰는 예상치를 왜 그렇게 잡았는지 매년 보고서로 내야 하고, 중간에 바꾸면 이사회 위원회에도 보고해야 해.","p0":"보험사는 책임준비금과 지급여력기준금액을 계산할 때 쓴 **계리가정의 산출 근거와 방법, 주요 변경 사항, 검증 결과**를 담고 현금흐름 모델링과 내부통제 내용까지 넣은 계리가정보고서를 매년 금감원에 내야 해요. 당국은 회사별·상품별 가정 수준과 변화를 비교해 이상 징후를 일찍 찾겠다고 했어요.","hi":1,"tn":["계리가정보고서","계리가정","듀레이션 갭","경영실태평가","비상위험준비금","법인보험대리점"]},{"id":"2026-11-04-2","date":"2026-11-04","tag":"정보보호","title":"보험권 첫 해킹, 미래에셋생명 점검이 길어지는 이유","thread":{"id":"insurer-security","name":"보험사 해킹과 정보보호"},"companies":["미래에셋생명"],"jobs":["리스크관리"],"summary":"미래에셋생명이 해킹당했는데 털린 정보가 계속 더 나와서, 금감원 점검도 길어지고 보상안도 아직 못 나오고 있어.","co":["미래에셋생명"],"p0":"미래에셋생명은 보험사 가운데 처음으로 해킹 사고가 확인된 곳이에요. 처음에는 이름, 주민등록번호, 휴대전화번호, 이메일, 주소, 연계정보, 계좌번호 유출을 알렸고, 이후 **퇴직연금 거래 정보**와 운전면허증 사본, 통장 사본, 퇴직소득 원천징수영수증 같은 2차 유출 정보도 확인됐어요.","hi":1,"tn":["현장점검","법정손해배상","운영위험","내부통제"]},{"id":"2026-11-04-3","date":"2026-11-04","tag":"해외 진출","title":"베트남 8곳·인도네시아 7곳, 금감원이 현지 감독당국을 서울로 부른 이유","thread":{"id":"overseas","name":"보험사 해외 진출"},"jobs":["상품개발","계리"],"summary":"우리나라 보험사들이 베트남이랑 인도네시아에서 장사를 많이 하니까, 금감원이 그 나라 감독기관 사람들을 불러서 규칙도 듣고 애로사항도 전했어.","p0":"금감원이 베트남과 인도네시아 보험감독당국의 인허가 담당자 등을 초청해 세미나를 열었어요. 두 나라 관계자들이 **보험시장 현황과 전망, 최근 인허가와 감독 현안**을 설명했어요.","hi":1,"tn":["인허가","감독당국","위험률"]},{"id":"2026-11-04-4","date":"2026-11-04","tag":"고령화·노후","title":"사망보험금을 살아서 월 35만 원씩, 시행 1년 신청자의 절반이 55~64세였어요","thread":{"id":"aging","name":"고령화와 보험"},"companies":["삼성생명","한화생명","교보생명","신한라이프","KB라이프"],"jobs":["상품개발","계리"],"summary":"죽은 뒤에 나오는 종신보험 사망보험금을 살아서 매달 받을 수 있는데, 해약환급금 기준이라 월 30만 원대라서 쓰는 사람이 대상의 0.65%뿐이야.","co":["삼성생명","한화생명","교보생명","신한라이프","KB라이프"],"p0":"사망보험금 유동화는 금리확정형 종신보험의 사망보험금 일부를 **살아 있을 때 연금처럼 나눠 받는** 제도예요. 2025년 10월 30일에 시행됐고, 5대 생명보험사(삼성생명·한화생명·교보생명·신한라이프·KB라이프)에 시행 1년간 3,257건이 접수됐어요.","hi":1,"tn":["사망보험금 유동화","종신보험","해약환급금","초고령사회"]},{"id":"2026-11-04-5","date":"2026-11-04","tag":"상품개발","title":"변호사를 보험사가 연결해준다고? 손보사 '현물급부'에 변협이 제동을 걸었어요","thread":{"id":"product-competition","name":"보험상품 개발 경쟁"},"companies":["하나손해보험","DB손해보험","메리츠화재","KB손해보험","롯데손해보험"],"jobs":["상품개발","보상·손해사정"],"summary":"교통사고 때 보험사가 변호사를 직접 붙여주는 특약이 늘었는데, 변호사 단체는 알선이 아니냐며 반발하고 있어.","co":["DB손해보험","KB손해보험","메리츠화재","롯데손해보험","하나손해보험"],"p0":"**현물급부**는 보험금을 현금으로 주는 대신 서비스를 직접 제공하는 방식이에요. 운전자보험 변호사 특약에서는 보험사가 제휴 법무법인이나 변호사를 연결해줘요. 하나손해보험이 5월에 처음 선보였고, 뒤이어 DB손해보험과 메리츠화재가 상품을 냈으며, 이달 KB손해보험과 롯데손해보험이 가세했어요.","hi":1,"tn":["현물급부","운전자보험","도덕적 해이"]},{"id":"2026-11-04-6","date":"2026-11-04","tag":"판매채널","title":"수수료 규제 뒤 GA 신계약이 줄었는데, 삼성화재만 늘었어요","thread":{"id":"sales-channel","name":"판매채널과 수수료"},"companies":["삼성화재","현대해상","메리츠화재","DB손해보험","KB손해보험"],"jobs":["영업·채널","계리"],"summary":"GA 수수료를 묶었더니 9월 신계약이 6월보다 12% 줄었는데, 6월이 미리 몰아 판 달이라 그대로 비교하면 안 되고 삼성화재만 늘었어.","co":["삼성화재","DB손해보험","현대해상","KB손해보험","메리츠화재"],"p0":"2026년 7월 1일 이후 체결 계약부터 GA가 소속 설계사에게 주는 첫해 보상 총액이 **월 보험료의 12배 이내**로 묶였어요(1200% 룰). 모집수수료뿐 아니라 정착지원금과 실적에 따른 시책도 한도에 들어가요.","hi":1,"tn":["1200% 룰","법인보험대리점","시책","분급","부당승환"]},{"id":"2026-11-03-1","date":"2026-11-03","tag":"건전성·자본","title":"보험사 예금보험료 2.5~3배 인상안, 한발 물러선 수정안이 나왔다","thread":{"id":"deposit-insurance","name":"예금보험료율 개편"},"jobs":["리스크관리","계리"],"summary":"예금 보호 한도를 1억으로 올리면서 보험사가 내는 예금보험료를 2~3배 올리자는 안이 나왔는데, 반발이 커서 덜 올리는 수정안이 나왔어.","p0":"2025년 9월 예금보호한도가 5,000만 원에서 1억 원으로 오르자, 예금보험기금의 손실에 대비할 재원이 필요해졌어요. 7월 연구용역안은 **은행 0.08%→0.13%, 생명보험 0.15%→0.40%, 손해보험 0.15%→0.50%**처럼 업권별 요율을 올리는 내용이었어요.","hi":1,"tn":["예금보험료율","예금자보호한도","예금보험기금","사업비"]},{"id":"2026-11-03-2","date":"2026-11-03","tag":"판매채널","title":"무료 케이크 수업에 갔다가 종신보험 가입? 공짜 강연 보험 영업 주의보","thread":{"id":"sales-channel","name":"판매채널과 수수료"},"jobs":["영업·채널","상품개발"],"summary":"공짜 강연이나 박람회에서 보험 권유받으면, 그게 저축인지 사망보험인지, 보장이 언제 끝나는지, 중간에 깨면 얼마 받는지 꼭 확인해.","p0":"금융당국에 따르면 무료 재테크 강연, 육아박람회 같은 곳의 보험 영업 민원이 꾸준히 들어오고 있어요. 무료 케이크 수업에서 **사전 안내 없이 보험을 권유받고**, 중도 해지 때 원금 손실이 크다는 설명을 못 들었다는 사례도 있었어요.","hi":1,"tn":["종신보험","해약환급금","해피콜","특약 만기","고지의무"]},{"id":"2026-11-03-3","date":"2026-11-03","tag":"상품개발","title":"700종신이 사라진 자리, 건강종신과 인출형 종신의 2파전","thread":{"id":"product-competition","name":"보험상품 개발 경쟁"},"companies":["신한라이프","KB라이프","동양생명","ABL생명"],"jobs":["상품개발","계리","영업·채널"],"summary":"7년만 지나면 낸 돈 다 돌려주던 종신보험이 막히자, 보험사들이 암 걸리면 미리 주는 종신보험이랑 살면서 꺼내 쓰는 종신보험으로 빈자리를 메우는 중이야.","co":["신한라이프","KB라이프","동양생명","ABL생명"],"p0":"700종신은 가입 7년 뒤 해약환급금이 낸 보험료의 100% 수준이 되는 종신보험이에요. 금감원은 **저축성 보험으로 오인될 수 있고, 환급 시점에 해지가 몰리면 보험사 지급 부담이 커질 수 있다**고 봤어요.","hi":1,"tn":["700종신","건강종신","인출형 종신보험","해지율","보험계약마진"]},{"id":"2026-11-02-1","date":"2026-11-02","tag":"자동차보험 · 손해율","title":"첫 차보험료가 46% 싸질 수도? 부모님 차·군 운전 경력도 인정돼요","thread":{"id":"auto-loss","name":"자동차보험 손해율과 보험료"},"jobs":["상품개발","언더라이팅"],"summary":"첫 차보험 비싸다고 그냥 내지 말고, 부모님 차보험에 이름 올렸던 거나 군대 운전 경력도 인정받으면 거의 절반까지 싸질 수 있어.","p0":"자동차보험료는 운전경력과 사고 이력으로 정해져서, 본인 명의 경력이 없는 청년은 보험료가 비싸요. 그런데 **부모 차보험의 종피보험자로 등록한 기간(최대 3년), 군 운전병, 장기렌터카, 관공서·법인 운전직, 해외 자동차보험 가입 경력**도 가입경력으로 인정받을 수 있어요.","hi":1,"tn":["가입경력 인정","종피보험자","운전자 한정 특약","할인특약"]},{"id":"2026-11-02-2","date":"2026-11-02","tag":"고령화·노후","title":"500조 퇴직연금에 '기금형' 문이 열린다, 한화금융 4사가 한꺼번에 움직인 이유","thread":{"id":"aging","name":"고령화와 보험"},"companies":["한화생명","한화손해보험"],"jobs":["상품개발","리스크관리"],"summary":"회사 퇴직연금을 전문 기금이 굴리는 방식이 열리면서, 한화 금융회사 4곳이 같이 준비하겠다고 나섰어.","co":["한화생명","한화손해보험"],"p0":"정부는 퇴직연금이 양적으로는 컸지만 **도입률·가입률 정체, 중도 인출, 낮은 수익률** 때문에 노후보장 기능이 부족하다고 보고, 사외적립 의무화와 기금형 퇴직연금 활성화를 내놨어요.","hi":1,"tn":["퇴직연금","기금형 퇴직연금","사외적립","수탁자 책임"]},{"id":"2026-11-01-1","date":"2026-11-01","tag":"소비자 보호","title":"나도 모르게 가입된 보험이 있다? 시민안전보험은 직접 청구해야 받아요","thread":{"id":"consumer-tips","name":"보험 소비자 유의사항"},"jobs":["보상·손해사정","상품개발"],"summary":"동네에서 보험료를 대신 내준 시민안전보험이 있는데, 다쳐도 내가 직접 청구 안 하면 못 받고 3년 지나면 끝이야.","p0":"시민안전보험은 지자체가 보험료를 내고, 그 지역에 주민등록이 된 사람(등록외국인 포함)을 **별도 신청 없이 자동 가입**시키는 보험이에요. 이사하면 새 주소지 보험으로 자동으로 바뀌어요.","hi":1,"tn":["시민안전보험","소멸시효","연간 총 보상한도","손해율"]},{"id":"2026-10-31-1","date":"2026-10-31","tag":"판매채널","title":"보험 97%를 창구에서 판 농협생명, 내년 3월 특례가 끝나면?","thread":{"id":"sales-channel","name":"판매채널과 수수료"},"companies":["NH농협생명"],"jobs":["영업·채널","상품개발","계리"],"summary":"농협생명은 보험을 거의 다 농협 창구에서 팔았는데, 그걸 가능하게 한 특별 규칙이 내년 3월에 끝날 수 있어서 판매 길을 고민해야 해.","co":["NH농협생명"],"p0":"은행·농축협 같은 금융기관보험대리점은 원래 **한 보험사 상품을 신규 모집액의 25%를 넘겨 팔 수 없어요**. 자산 2조 원 미만 지역 농·축협은 2012년부터 특례로 이 규제를 유예받아 농협보험 상품만 팔아 왔고, 2016년과 2021년 두 번 연장됐어요.","hi":1,"tn":["방카슈랑스","25% 룰","농·축협 판매 특례","보험계약마진","손실계약"]},{"id":"2026-10-31-2","date":"2026-10-31","tag":"보험사 실적","title":"보험 계열사가 가른 금융지주 성적표, 하나만 마이너스였던 이유","thread":{"id":"earnings","name":"보험사 실적"},"companies":["하나손해보험","하나생명","신한라이프","동양생명","ABL생명","KB손해보험","KB라이프"],"jobs":["계리","리스크관리"],"summary":"금융지주들 실적을 보면 보험 자회사가 얼마나 버느냐가 차이를 만들었는데, 하나금융은 보험 자회사들이 적자라서 오히려 깎아 먹었어.","co":["신한라이프","KB라이프","동양생명","ABL생명","하나생명","KB손해보험","하나손해보험"],"p0":"4대 금융지주의 3분기 누적 순이익에서 보험 계열사가 보탠 몫은 KB 15.4%, 신한 7.78%, 우리 3.13%, 하나 −2.46%였어요. 하나생명도 작년 302억 원 흑자에서 **47억 원 적자로 돌아섰어요**.","hi":1,"tn":["계리가정","이익 기여도","감가상각비","투자손익","보험손익"]},{"id":"2026-10-31-3","date":"2026-10-31","tag":"보험사기","title":"보험을 파는 사람이 보험사기에? 설계사·손해사정사 29명 제재","thread":{"id":"fraud","name":"보험사기 대응"},"jobs":["보상·손해사정","언더라이팅","영업·채널"],"summary":"보험을 파는 설계사들이 오히려 교통사고를 꾸미거나 가짜 입원을 도와서 보험금을 타내다 걸려서 29명이 자격 취소나 정지를 당했어.","p0":"금융위원회가 금감원 검사 결과를 바탕으로 보험사기에 연루된 보험업 종사자 29명을 제재했어요. **19명은 등록취소**, 7명은 업무정지 180일, 3명은 업무정지 90일을 받았어요.","hi":1,"tn":["보험사기","등록취소","손해사정사","고지의무","손해율"]},{"id":"2026-10-31-4","date":"2026-10-31","tag":"자산운용","title":"생보사가 9월까지 6.2조 원을 '생산적 금융'에, 목표를 넘긴 걸까?","thread":{"id":"productive-finance","name":"생산적 금융과 보험 자산운용"},"jobs":["리스크관리","계리"],"summary":"생명보험회사들이 올해 9월까지 첨단산업 같은 곳에 6조 원 넘게 돈을 대줬는데, 계산 기준을 엄격하게 해도 목표보다 많이 했대.","p0":"생명보험업계가 9월까지 첨단산업, 사회기반시설 같은 생산적 금융에 6조 2,000억 원을 공급했어요. 주거용 부동산 개발 대출 1조 2,800억 원을 빼면 4조 9,200억 원이고, 이는 목표 3조 6,000억 원보다 37% 많아요. $$\\frac{4.92}{3.6}\\approx 1.37$$","hi":1,"tn":["생산적 금융","신용생명보험","듀레이션","지급여력비율"]},{"id":"2026-10-31-5","date":"2026-10-31","tag":"해외 진출","title":"미국 보험사를 통째로 산 DB손해보험, 이제 '얼마나 버느냐'의 시간","thread":{"id":"overseas","name":"보험사 해외 진출"},"companies":["DB손해보험"],"jobs":["리스크관리","상품개발"],"summary":"DB손해보험이 미국 보험회사를 2조 원 넘게 주고 통째로 샀는데, 이제는 그 돈만큼 실제로 이익을 내는지가 중요해졌어.","co":["DB손해보험"],"p0":"DB손해보험은 2025년 9월 계약을 맺고 2026년 5월 미국 특화보험사 포테그라 지분 100%를 16억 5천만 달러에 사들였어요. **국내 보험사의 첫 미국 보험사 인수이자 업계 최대 인수합병**이에요.","hi":1,"tn":["특화보험사","배당성향","자본 효율성","별도 기준"]},{"id":"2026-10-30-1","date":"2026-10-30","tag":"감독·계리","title":"금감원 \"손해율·사업비 가정 아직 부족\", 모든 보험사 11월 말까지 개선계획 내야","thread":{"id":"actuarial-supervision","name":"계리감독 강화"},"jobs":["계리","리스크관리","상품개발"],"summary":"보험사가 앞으로 나갈 돈을 계산할 때 쓰는 전제, 그러니까 손해율이나 사업비 예상을 대충 잡은 사례가 나와서 금감원이 모든 보험사에 11월 말까지 고칠 계획을 내라고 한 거야. 이 전제가 틀리면 보험사 실적과 건전성 숫자가 통째로 틀어지거든.","p0":"금감원이 9월에 생명보험사 3곳, 손해보험사 3곳을 점검해 **손해율과 사업비 가정**을 세우는 방식에서 미흡한 사례를 찾았어요.","hi":1,"tn":["계리가정","최선추정부채","보험계약마진","예실차","목표손해율","사업비"]},{"id":"2026-10-30-2","date":"2026-10-30","tag":"실손보험","title":"11월부터 1·2세대 실손 보험료 할인, 갈아탈까 말까","thread":{"id":"silson-reform","name":"실손보험 개편"},"jobs":["상품개발","계리","보상·손해사정"],"summary":"예전 실손보험 가입자한테 보장을 줄이는 대신 보험료를 크게 깎아주는 제도가 11월부터 시작돼. 병원을 잘 안 가면 이득이지만, 비급여 치료를 자주 받으면 오히려 손해일 수 있어서 각자 따져봐야 해.","p0":"대상은 2013년 3월 이전에 가입한 1·2세대 실손 가운데 재가입 주기가 없는 계약으로, **약 1,700만 명**이에요. 11월부터 시행돼요.","hi":1,"tn":["실손보험","비급여","자기부담률","역선택","재가입 주기"]},{"id":"2026-10-30-3","date":"2026-10-30","tag":"보험사 실적","title":"보험 영업은 더 잘했는데 순이익은 줄었다? KB 보험계열사 3분기 실적","thread":{"id":"earnings","name":"보험사 실적"},"companies":["KB손해보험","KB라이프"],"jobs":["리스크관리","계리"],"summary":"KB 보험회사들이 보험 장사로는 돈을 더 벌었는데, 모아둔 돈을 굴려서 번 투자 수익이 크게 줄어서 전체 순이익은 줄었어.","co":["KB라이프","KB손해보험"],"p0":"KB라이프는 순이익이 줄었지만, 앞으로 나눠서 이익으로 잡힐 신계약 보험계약마진이 **3조 6,994억 원으로 15.8% 늘었어요**. KB손해보험의 신계약 보험계약마진은 5% 줄었어요.","hi":1,"tn":["보험손익","투자손익","보험계약마진","지급여력비율"]},{"id":"2026-10-29-1","date":"2026-10-29","tag":"자동차보험 · 손해율","title":"9월 자동차보험 손해율 9%p 개선, 그런데 업계는 왜 웃지 못할까","thread":{"id":"auto-loss","name":"자동차보험 손해율과 보험료"},"jobs":["계리","상품개발","보상·손해사정"],"summary":"자동차보험에서 보험사가 받은 돈 대비 내준 돈의 비율이 9월에 반짝 좋아졌지만, 여전히 손해 보는 선을 넘고 있고 수리비·인건비가 계속 올라서 다시 나빠질 거라 보험사들은 안심 못 하는 상황이야.","p0":"대형 손보사 4곳의 1~9월 누적 자동차보험 손해율은 **84.7%**로 작년보다 0.8%p 낮아졌어요. 9월 한 달은 85.0%로, 작년 같은 달보다 약 9%p 낮았어요.","hi":1,"tn":["손해율","합산비율","기저효과","정비수가","휴업손해"]},{"id":"2026-10-21-1","date":"2026-10-21","tag":"보험사 실적","title":"상반기 순이익 9,045억 원인데 배당은 못 한다? 저평가 명단을 앞둔 한화생명의 고민","thread":{"id":"insurer-valueup","name":"보험사 기업가치 제고"},"companies":["한화생명","한화손해보험"],"jobs":["계리","리스크관리"],"summary":"한화생명은 반년 동안 9천억 원 넘게 벌었어도 이익잉여금의 97%가 해약환급금준비금이라 배당할 돈이 모자라고, 주가도 한 달 새 25% 빠졌어.","co":["한화생명","한화손해보험"],"p0":"한국거래소는 11월 2일 첫 저평가 기업 명단을 공표해요. 산정 기준일은 22일이고 최근 20거래일 평균 시가총액을 쓰며, 코스피 상장사 중 업종별로 최근 6반기 연속 주가순자산비율 하위 25%가 대상이에요. 22일까지 기업가치 제고 계획을 공시하면 1년간 공표가 면제돼요. 한화손해보험은 20일에 냈지만 한화생명은 **발표 시점과 내용이 아직 정해지지 않았어요.** KB증권은 9월에 두 회사를 모두 장기 저평가 기업으로 분류했어요.","hi":1,"tn":["주가순자산비율","이익잉여금","해약환급금준비금","배당가능이익","700종신"]},{"id":"2026-10-21-2","date":"2026-10-21","tag":"상품개발","title":"종신보험 신계약 2년 새 20% 줄었다, '700종신' 막힌 생보사들이 꺼낸 카드","thread":{"id":"product-competition","name":"보험상품 개발 경쟁"},"companies":["흥국생명","한화생명","삼성생명"],"jobs":["상품개발","계리"],"summary":"700종신이 막힌 뒤 종신보험 신계약이 2년 새 약 20% 줄어서, 흥국·한화·삼성생명이 돌려받거나 꺼내 쓰는 기능을 더한 종신보험을 내놨어.","co":["삼성생명","한화생명","흥국생명"],"p0":"금융감독원 통계(22개 생명보험사)에서 종신보험 신계약 건수는 2024년 상반기 109만 3,113건에서 올해 상반기 **86만 4,340건**으로 줄었어요. 반면 보장성보험 전체 신계약 건수는 518만 248건에서 530만 8,540건으로 늘었어요. 올해 상반기 개인 보장성보험 신계약금액 66조 2,210억 원 중 종신보험은 26조 5,504억 원으로 약 40%예요.","hi":1,"tn":["종신보험","700종신","인출형 종신보험","정기보험","부당승환"]},{"id":"2026-10-20-1","date":"2026-10-20","tag":"보험사기","title":"오랫동안 보험료를 안 냈는데 사고가 나자 밀린 보험료를 내고 거액 보험금? '납입최고'의 빈틈","thread":{"id":"fraud","name":"보험사기 대응"},"jobs":["언더라이팅","보상·손해사정","계리"],"summary":"보험료를 오래 안 내서 독촉장이 안 닿았다는 이유로 계약이 살아 있다가, 사고 나면 밀린 돈만 내고 보험금 받는 게 문제라서 연체가 길면 효력을 멈추자는 제안이 나왔어.","p0":"보험료를 내지 못하면 보험사가 내라고 알리는 독촉(납입최고)을 하고, **정해진 기간 안에 내지 않으면 계약 효력이 상실**돼요. 효력이 상실된 계약도 일정 기간 안에 밀린 보험료를 내고 부활을 청구할 수 있어요.","hi":1,"tn":["납입최고","효력상실","부활","역선택","의료자문"]},{"id":"2026-10-20-2","date":"2026-10-20","tag":"건전성·자본","title":"부실 손보사 하나 정리에 4년 넘게, 예금보험공사 돈은 1조 원 넘게? MG손해보험이 남긴 숙제","thread":{"id":"insurer-resolution","name":"부실 보험사 정리"},"jobs":["리스크관리","계리"],"summary":"부실해진 손해보험사 하나를 정리하는 데 4년 넘게 걸리고 예금보험공사 지원이 1조 원을 넘을 수 있어서, 일찍 보험료를 조정하고 법도 고치자는 얘기가 나왔어.","p0":"한민수 의원은 MG손해보험이 부실금융기관으로 지정된 뒤 올해 10월 주식매매계약을 맺기까지 **4년 넘게** 걸렸다고 짚었어요. 그동안 예금보험공사가 **가교보험사 설립에 400억 원**을 넣었고, 앞으로 추가 지원은 1조 원을 웃돌 것으로 예상된다고 했어요.","hi":1,"tn":["부실금융기관","가교보험사","계약이전","예금보험기금","손해율"]},{"id":"2026-10-20-3","date":"2026-10-20","tag":"보험사 실적","title":"주가가 순자산의 0.22배? 한화손해보험이 '몸집보다 가치'를 내건 기업가치 제고 계획","thread":{"id":"insurer-valueup","name":"보험사 기업가치 제고"},"companies":["한화손해보험"],"jobs":["계리","상품개발","리스크관리"],"summary":"한화손보는 주가가 순자산의 0.22배밖에 안 돼서, 덩치 키우기보다 자본 부담 큰 신계약을 골라 줄이고 주주환원을 꾸준히 하겠다고 계획을 냈어.","co":["삼성화재","DB손해보험","현대해상","한화손해보험"],"p0":"주가순자산비율은 주가를 주당 순자산으로 나눈 값이에요. 한화손해보험은 2분기 기준 **0.22배**로 삼성화재·DB손해보험·현대해상 평균 0.58배에 못 미치고, 중장기에 1배 이상을 목표로 해요.","hi":1,"tn":["주가순자산비율","자기자본이익률","보험계약마진","지급여력비율","주주환원"]},{"id":"2026-10-20-4","date":"2026-10-20","tag":"고령화·노후","title":"사망원인 3위 폐렴까지, 삼성생명 시니어 건강보험이 장기요양 '이후'를 파고든 이유","thread":{"id":"aging","name":"고령화와 보험"},"companies":["삼성생명"],"jobs":["상품개발","언더라이팅"],"summary":"삼성생명이 시니어 건강보험에 사망원인 3위 폐렴 보장을 넣고, 장기요양 판정 뒤에 필요한 치료랑 재활을 한 특약으로 묶었어. 중증도에 따라 보험금도 달라져.","co":["삼성생명"],"p0":"지난 7월 처음 나온 '삼성 시니어대표건강보험'은 치매·장기요양 보장에 뇌질환·관절질환 보장을 더한 시니어 전용 상품이에요. 이번에 **종합보장형**과 **장기요양 통합치료형**으로 개정해 21일 출시해요.","hi":1,"tn":["장기요양","저해약환급금형","폐렴 중증도 척도","간편고지","해약환급금"]},{"id":"2026-10-19-1","date":"2026-10-19","tag":"건전성·자본","title":"예금보험료율 0.15%가 0.40%·0.50%로? 국정감사에서 불거진 보험업권 1조 4,997억 원 부담","thread":{"id":"deposit-insurance","name":"예금보험료율 개편"},"jobs":["리스크관리","계리"],"summary":"보험사가 내는 예금보험료를 연구용역안대로 올리면 생보는 순이익의 18.7%, 손보는 7.9%가 더 나가는데, 국감에서 근거를 공개하라는 요구가 나왔어.","p0":"10월 19일 정무위원회 국정감사에서 유동수 정무위원장은 예금보험공사 연구용역안이 보험업권에 주는 부담을 지적했어요. 연구용역안은 **생명보험 0.15%→0.40%, 손해보험 0.15%→0.50%**로 현행의 약 2.7배, 약 3.3배예요. 지난해 9월 금융위원회 보고자료의 인상안(생명보험 0.171%, 손해보험 0.154%)보다도 높아요.","hi":1,"tn":["예금보험료율","예금보험기금","목표기금제","국정감사"]},{"id":"2026-10-18-1","date":"2026-10-18","tag":"건전성·자본","title":"보험료를 못 내 멈춘 생명보험 104조 원, ABL생명은 1년 새 두 배 가까이","thread":{"id":"rates","name":"금리와 보험료"},"companies":["ABL생명","교보생명","삼성생명","한화생명","미래에셋생명","흥국생명","신한라이프","동양생명"],"jobs":["계리","리스크관리"],"summary":"보험료를 못 내서 멈추거나 해지된 생명보험이 104조 원어치나 되고 1년 새 5조 원 넘게 늘었어. 금리가 오르고 살림이 빠듯해지니까 보험부터 끊는 거라, 보험사는 미래 이익이 줄고 사람들은 보장이 비는 문제가 생겨.","co":["삼성생명","한화생명","교보생명","신한라이프","미래에셋생명","동양생명","ABL생명","흥국생명"],"p0":"보험료를 못 내 효력이 멈추거나 중간에 해지된 생명보험 계약의 잔액이 **104조 6,515억 원**으로 1년 새 5조 5,342억 원(5.58%) 늘었어요.","hi":1,"tn":["효력상실","해지율","보험계약마진","부활","보장공백"]},{"id":"2026-10-18-2","date":"2026-10-18","tag":"건전성·자본","title":"생보사 이익잉여금 63조 원, 그런데 절반 가까이는 배당도 못 하는 돈?","thread":{"id":"kics","name":"지급여력제도(킥스)"},"companies":["삼성생명","흥국생명","DB생명","미래에셋생명","한화생명","동양생명","교보생명","신한라이프"],"jobs":["계리","리스크관리","상품개발"],"summary":"생보사들이 쌓아둔 이익이 63조 원 가까이 되는데, 그중 절반 가까이는 법 때문에 묶어둬야 하는 준비금이라 배당도 못 하고 자본으로 쓰기도 어려워. 그래서 작년에 배당한 상장 생보사는 삼성생명뿐이었어.","co":["삼성생명","한화생명","교보생명","신한라이프","미래에셋생명","동양생명","흥국생명","DB생명"],"p0":"22개 생보사의 6월 말 이익잉여금은 **62조 8,991억 원**으로 1년 새 4조 1,100억 원(7.0%) 늘었어요. 삼성생명이 16조 3,100억 원으로 규모와 증가액 모두 1위였고, 업계 증가분의 42.5%를 차지했어요.","hi":1,"tn":["이익잉여금","해약환급금준비금","기본자본","투자손익","보험손익"]},{"id":"2026-10-15-1","date":"2026-10-15","tag":"판매채널","title":"1200% 룰 밖에 있는 연금보험, 그래도 '차익거래'는 막으라는 금감원","thread":{"id":"sales-channel","name":"판매채널과 수수료"},"jobs":["상품개발","영업·채널","계리"],"summary":"보장성보험 수수료를 묶는 규칙이 연금보험에는 안 걸리니까 판매가 연금보험으로 몰릴 수 있잖아. 그래서 금감원이 연금보험도 수수료랑 환급금 합이 낸 돈보다 커지는 일이 없게 보험사가 알아서 관리하라고 했어.","p0":"700종신 판매가 위축되자 생보사와 법인보험대리점 채널에서 **1200% 룰 적용을 받지 않는 연금보험**이 대체 상품으로 떠오르고 있어요.","hi":1,"tn":["1200% 룰","차익거래","시책","해약환급금","수수료 환수"]},{"id":"2026-10-15-2","date":"2026-10-15","tag":"상품개발","title":"안 쓴 치료비 보장을 내년으로 넘긴다? 흥국화재 '한도이연형'이 6개월 독점권을 받은 이유","thread":{"id":"product-competition","name":"보험상품 개발 경쟁"},"companies":["흥국화재"],"jobs":["상품개발","계리"],"summary":"보통 치료비 보험은 그해 안 쓰면 보장이 그냥 사라지는데, 흥국화재가 안 쓴 걸 다음 해로 넘길 수 있게 만들어서 6개월 독점권을 받았어. 치료가 한 해에 몰리는 암 같은 병에 유리하고, 치료마다 따로 보장하는 것보다 보험료도 싸대.","co":["흥국화재"],"p0":"흥국화재가 손해보험협회에서 **'한도이연형 구조'**로 6개월 배타적사용권을 받았어요. 보장 질병을 처음 진단받은 뒤 그해 쓰지 않은 연간 보장한도를 다음 해로 넘길 수 있고, 이월은 최대 5회까지 돼요.","hi":1,"tn":["배타적사용권","연간 보장한도","한도이연","담보"]},{"id":"2026-10-15-3","date":"2026-10-15","tag":"건전성·자본","title":"1조 원을 갚을 날이 다가온다, 한화생명이 최대 8,000억 원 자본확충에 나선 이유","thread":{"id":"kics","name":"지급여력제도(킥스)"},"companies":["한화생명"],"jobs":["리스크관리","계리"],"summary":"한화생명이 예전에 빌린 1조 원을 내년부터 먼저 갚아야 하고 계열사에도 돈을 많이 넣어서, 건전성 비율이 떨어질까 봐 최대 8,000억 원을 새로 빌려 자본을 채우려는 거야.","co":["한화생명"],"p0":"한화생명이 **최대 8,000억 원** 규모의 자본성 증권 발행을 추진하고, 후순위채가 유력하다고 알려졌어요. 국내 증권사에 주관사 제안 요청서를 보냈고 11월 안에 수요예측과 납입을 마칠 계획이에요.","hi":1,"tn":["후순위채","보완자본","조기상환권","지급여력비율","수요예측"]},{"id":"2026-10-14-1","date":"2026-10-14","tag":"상품개발","title":"'700종신'이 사라진 자리, 생보사들은 '인출'로 종신보험을 다시 짰다","thread":{"id":"product-competition","name":"보험상품 개발 경쟁"},"companies":["삼성생명","한화생명","흥국생명"],"jobs":["상품개발","계리","영업·채널"],"summary":"7년 지나면 낸 돈 다 돌려주던 종신보험이 판매 중단되자, 삼성생명이랑 한화생명이 사망보장은 그대로 두고 낸 보험료를 나중에 꺼내 쓸 수 있는 종신보험을 새로 내놨어.","co":["삼성생명","한화생명","흥국생명"],"p0":"7년 뒤 낸 보험료를 100% 넘게 돌려주던 **700종신**은 유지율이 낮고 원금 도달 직후 대량 해지가 나면 건전성이 나빠질 수 있다는 당국 우려로 9월 21일부터 사실상 판매가 멈췄어요.","hi":1,"tn":["종신보험","단기납 종신보험","체증형","납입면제","해지율"]},{"id":"2026-10-13-1","date":"2026-10-13","tag":"인수합병","title":"2조 원을 바랐던 롯데손해보험, 6,933억 원에 신한금융 품으로","thread":{"id":"insurer-mna","name":"보험사 인수합병과 사업 확장"},"companies":["롯데손해보험"],"jobs":["계리","리스크관리"],"summary":"신한금융이 롯데손해보험을 6,933억 원에 사기로 했어. 원래 2조 원 넘게 받고 싶어 했는데, 자본 상태가 나빠서 값이 확 떨어졌고, 신한은 앞으로 증자 같은 돈을 더 넣어야 해.","co":["롯데손해보험"],"p0":"신한금융지주가 10월 13일 사모펀드 제이케이엘파트너스가 가진 롯데손해보험 지분 **77.04%를 6,933억 원**에 사는 계약을 맺었어요. 금융당국 승인을 거쳐 남은 지분 22.96%도 확보해 완전자회사로 만든 뒤 신한이지손해보험과 합칠 계획이에요.","hi":1,"tn":["기본자본 지급여력비율","경영개선요구","완전자회사","유상증자","보험계약마진"]},{"id":"2026-10-13-2","date":"2026-10-13","tag":"기후·재해","title":"35도가 넘으면 바로 지급? 보험연구원이 꺼낸 '지수형 기후보험'","thread":{"id":"climate-insurance","name":"기후위기와 보험"},"jobs":["상품개발","계리"],"summary":"폭염 때문에 장사가 안 돼도 기존 보험은 손해를 계산하기 어려워서 보상이 잘 안 돼. 그래서 보험연구원이 기온이 35도를 넘는 것처럼 조건만 맞으면 바로 돈을 주는 지수형 보험을 늘리자고 했어.","p0":"보험연구원이 10월 13일 세미나에서 기후위기로 자연재해가 커지면서 **기존 실손형 보험이 못 메우는 보장 공백**이 넓어지고 있다고 진단했어요. 소상공인의 풍수해보험 가입률은 4.6%에 그쳐요.","hi":1,"tn":["지수형 보험","실손형 보험","기저위험","풍수해보험"]},{"id":"2026-10-12-1","date":"2026-10-12","tag":"감독·계리","title":"보험금은 통계로 예상하는 건데, 목표에 맞춰 늘리라고? 갱신보험 손해율에 칼 빼든 금감원","thread":{"id":"actuarial-supervision","name":"계리감독 강화"},"jobs":["계리","상품개발","리스크관리"],"summary":"보험사가 앞으로 나갈 보험금을 적게 예상하면 이익이 커 보이니까, 금감원이 갱신보험 손해율에 목표를 정해서 그보다 낮으면 보험금 예상액을 늘리라고 하려는 거야. 업계는 통계 말고 목표로 거꾸로 계산하는 건 이상하다고 반발해.","p0":"금감원이 **실손보험을 뺀 갱신보험**의 손해율 산정 기준을 통일하는 지침을 준비하고 있어요. 보험사가 예상한 손해율이 당국이 정한 목표손해율보다 낮으면, 미래 보험금 지급 예상액을 늘려 목표에 맞추게 하는 방식이에요.","hi":1,"tn":["목표손해율","계리가정","갱신보험","보험계약마진","손해율"]},{"id":"2026-10-12-2","date":"2026-10-12","tag":"판매채널","title":"보험 광고 규정 위반 4만 7천 건, 그런데 제재금은 10건? '걸리면 지우면 그만'의 함정","thread":{"id":"sales-channel","name":"판매채널과 수수료"},"jobs":["영업·채널","상품개발"],"summary":"보험 광고가 규칙을 어긴 게 4만 7천 건 넘게 걸렸는데, 대부분 글만 지우고 끝나서 돈으로 제재받은 건 10건뿐이었어. 국회에서 이러면 '지우면 그만'이 된다고 따졌어.","p0":"박성훈 의원이 금융당국에서 받은 자료에 따르면 손해보험협회 신고센터에서 확인된 보험 광고 심의 규정 위반이 4년 반 동안 **4만 7,078건**이었어요. 그중 61.4%는 사전 심의를 아예 받지 않은 광고였고, 매체는 블로그가 3만 9,109건으로 가장 많았어요.","hi":1,"tn":["광고 심의","시정조치","제재금","금융소비자보호법","자율규제"]},{"id":"2026-10-08-1","date":"2026-10-08","tag":"판매채널","title":"계약이 두 달 만에 깨지면 수수료를 120% 토해내라? 국감에 처음 선 대형 보험대리점 대표","thread":{"id":"sales-channel","name":"판매채널과 수수료"},"jobs":["영업·채널","계리"],"summary":"보험 계약이 두 달 만에 깨지면 설계사가 받은 수수료를 돌려줘야 하는데, 한 대형 대리점은 보험사가 받아가는 것보다 많은 최대 120%를 설계사한테 받아가서 국감에서 혼났어. 못 갚으면 설계사 빚으로 남는 구조라 당국이 살펴보겠대.","p0":"10월 8일 금융위원회 국정감사에서 **대형 법인보험대리점 대표가 처음으로 일반 증인**으로 나왔어요. 소속 설계사 위촉계약에 계약이 초기에 해지되면 받은 수수료의 최대 120%를 돌려받는 조항이 있었기 때문이에요.","hi":1,"tn":["법인보험대리점","수수료 환수","지급보증보험","부당승환","1200% 룰"]},{"id":"2026-10-08-2","date":"2026-10-08","tag":"자동차보험 · 손해율","title":"'8주룰' 한 달, 합의 재촉하면 신고하세요? 손보협회가 경상환자 피해 신고센터를 여는 이유","thread":{"id":"auto-loss","name":"자동차보험 손해율과 보험료"},"jobs":["보상·손해사정","계리"],"summary":"가벼운 교통사고 환자가 8주 넘게 치료받으려면 심사를 받게 됐는데, 보험사가 이걸 핑계로 합의를 재촉하거나 보증을 끊을까 봐 손해보험협회가 피해 신고센터를 열었어.","p0":"9월 10일 이후 사고로 다친 **상해등급 12~14급 경상환자**가 8주를 넘겨 치료받으려면, 사고일부터 7주 안에 진단서와 진료기록부 등을 내고 치료 필요성 검토를 받아야 해요.","hi":1,"tn":["경상환자","상해등급","지급보증","향후치료비","손해율"]},{"id":"2026-10-08-3","date":"2026-10-08","tag":"인수합병","title":"삼성생명이 해외에서 2조 원을 빌린다? 30년 만기 신종자본증권에 담긴 '해외 확장' 신호","thread":{"id":"insurer-mna","name":"보험사 인수합병과 사업 확장"},"companies":["삼성생명"],"jobs":["리스크관리","계리"],"summary":"삼성생명이 해외에서 30년짜리로 최대 2조 원을 빌리기로 했는데, 자본처럼 쳐주는 채권이라 해외 보험사를 사들여도 회사 체력과 배당을 지키려는 준비로 보는 사람이 많아.","co":["삼성생명"],"p0":"삼성생명은 10월 8일 **15억 달러(약 2조 원) 한도의 30년 만기 해외 신종자본증권** 발행을 결정했어요. 글로벌 신용평가사 등급을 받고 해외 기관투자자 대상 투자설명회를 거쳐 올해 안에 발행할 계획이에요.","hi":1,"tn":["신종자본증권","가용자본","지급여력비율","투자설명회"]},{"id":"2026-10-06-1","date":"2026-10-06","tag":"상품개발","title":"보험 '특허' 신청이 줄었다, 생보는 2배 늘고 손보는 반토막 난 이유","thread":{"id":"product-competition","name":"보험상품 개발 경쟁"},"companies":["한화손해보험","DB손해보험","삼성생명","교보생명","한화생명","흥국생명","흥국화재","KB손해보험","삼성화재"],"jobs":["상품개발","계리"],"summary":"보험 상품도 특허처럼 몇 달 동안 혼자 팔 수 있는 권리(배타적사용권)가 있는데, 손보사들이 보장 한도만 키운 상품으로 따내던 길이 막혀서 신청이 반으로 줄었어. 대신 생보사들은 새로운 구조의 상품으로 두 배 넘게 신청했어.","co":["삼성생명","한화생명","교보생명","흥국생명","삼성화재","DB손해보험","KB손해보험","한화손해보험","흥국화재"],"p0":"올해 1~9월 보험상품 **배타적사용권** 신청은 36건으로 1년 전보다 12.20% 줄었고, 부여도 36건에서 31건으로 줄었어요.","hi":1,"tn":["배타적사용권","수용률","상품위원회","역선택"]},{"id":"2026-10-05-1","date":"2026-10-05","tag":"건전성·자본","title":"전체 비율은 160%인데 기본자본은 마이너스? 내년 1월 시작하는 기본자본 킥스 50% 규제, 5곳이 미달","thread":{"id":"kics","name":"지급여력제도(킥스)"},"companies":["롯데손해보험","하나손해보험","하나생명"],"jobs":["리스크관리","계리"],"summary":"보험사 건전성 점수는 진짜 자기 돈(기본자본)이랑 빌린 돈 성격의 자본(보완자본)을 합쳐서 매기는데, 내년부터는 진짜 자기 돈만으로도 50%를 넘겨야 해. 롯데손보는 이게 마이너스라서 회사를 사려는 쪽도 돈을 더 넣어야 하는 상황이야.","co":["하나생명","DB생명","롯데손해보험","하나손해보험"],"p0":"금융당국은 2027년 1월부터 보험사가 **기본자본 지급여력비율을 50% 이상** 유지하도록 하는 규제를 시작해요. 손실흡수력이 큰 자본만으로 계산하는 비율이라, 전체 비율만 높여서는 안 되고 자본의 질을 높여야 해요. 다만 2035년 말까지 경과조치가 있어요.","hi":1,"tn":["기본자본","보완자본","기본자본 지급여력비율","경과조치","공개매각"]},{"id":"2026-10-04-1","date":"2026-10-04","tag":"회계제도","title":"생명보험사 부채가 1년 새 87조 원 줄었다? 계약이 사라진 게 아니라 금리가 바꾼 숫자","thread":{"id":"ifrs17","name":"새 회계기준과 보험부채"},"companies":["삼성생명","한화생명","교보생명","신한라이프","NH농협생명","동양생명","흥국생명","DB생명","하나생명"],"jobs":["계리","리스크관리"],"summary":"생명보험사 빚(보험부채)이 1년 만에 87조나 줄었는데, 계약이 없어진 게 아니라 금리가 올라서 미래에 줄 돈을 지금 가치로 작게 계산했기 때문이야. 금리 오르면 보험사가 가진 채권 값도 떨어지니까 좋아졌다고 단정하면 안 돼.","co":["삼성생명","한화생명","교보생명","신한라이프","NH농협생명","동양생명","흥국생명","하나생명","DB생명"],"p0":"생명보험협회 공시에 따르면 국내 생보사 22곳의 **보험계약부채**는 2026년 2분기 말 530조 4,585억 원으로, 1년 전보다 **87조 573억 원(14.10%)** 줄었어요. 22곳 중 BNP파리바카디프생명만 늘었어요.","hi":1,"tn":["보험계약부채","할인율","유동성프리미엄","듀레이션","기타포괄손익"]},{"id":"2026-10-01-1","date":"2026-10-01","tag":"판매채널","title":"\"받고 받고 또 받고\" 홈쇼핑 보험광고, 불완전판매 3배인데 5년간 경고는 단 1건","thread":{"id":"sales-channel","name":"판매채널과 수수료"},"jobs":["영업·채널","상품개발"],"summary":"홈쇼핑에서 '받고 받고 또 받고' 하는 보험광고 많이 보지? 그걸 보고 가입한 계약은 잘못 팔린 비율이 다른 경로의 3배고 금방 깨지는 경우도 많은데, 제재는 5년간 경고 1번뿐이어서 금감원이 기준을 세게 바꾸겠다고 한 거야.","p0":"금감원이 10월 1일 생명·손해보험협회와 함께 보험사와 홈쇼핑 법인보험대리점 13곳의 준법감시인을 불러 **보험 방송광고 건전화**를 논의했어요. 지난해 보험 방송광고는 하루 평균 1,121회로 1년 새 66.9% 늘었어요.","hi":1,"tn":["불완전판매비율","13회차 유지율","준법감시인","법인보험대리점","자율규제"]},{"id":"2026-10-01-2","date":"2026-10-01","tag":"인수합병","title":"보험사가 캐피탈과 저축은행을 산다? 한화생명이 4,400억 원으로 애큐온캐피탈을 품은 이유","thread":{"id":"insurer-mna","name":"보험사 인수합병과 사업 확장"},"companies":["한화생명"],"jobs":["리스크관리","계리"],"summary":"한화생명이 4,400억 원을 내고 캐피탈 회사랑 그 밑의 저축은행까지 사들였어. 보험만으로는 성장이 더뎌서 대출·증권까지 다 하는 종합금융그룹이 되겠다는 건데, 산 저축은행이 요즘 돈을 잘 못 벌고 자본도 묶이니까 잘 굴러갈지는 지켜봐야 해.","co":["한화생명"],"p0":"한화생명이 사모펀드 운용사 센트로이드PE와 함께 애큐온캐피탈을 인수하기로 하고, **4,400억 원에 지분 50.54%**를 확보해요. 애큐온캐피탈이 100% 가진 애큐온저축은행도 한화생명의 손자회사가 돼요.","hi":1,"tn":["여신전문금융업","손자회사","유상증자","종합금융투자사업자","대주주 변경 승인"]},{"id":"2026-05-05-b1","date":"2026-05-05","tag":"실손보험","title":"4세대보다 30% 싼 5세대 실손 출시, 11월엔 1·2세대 전환 할인도","thread":{"id":"silson-reform","name":"실손보험 개편"},"jobs":["상품개발","계리"],"basic":true,"summary":"5세대 실손이 나왔는데 4세대보다 30%쯤 싸. 대신 가벼운 비급여는 덜 보장해. 옛날 1·2세대 가입자는 11월부터 갈아타면 3년 동안 반값 할인을 받을 수 있어.","p0":"2026년 5월 6일부터 생명 7곳, 손해 9곳 등 **16개 보험사**가 5세대 실손을 팔기 시작했어요. 보험료는 4세대보다 약 30%, 1·2세대보다 50% 이상 낮아요.","hi":1,"tn":["실손보험","재가입 주기","역선택","선택형 할인특약","비급여"]},{"id":"2026-03-31-b1","date":"2026-03-31","tag":"보험사기","title":"적발 인원은 줄었는데 금액은 역대 최대, 보험사기가 '고액화'된다","thread":{"id":"fraud","name":"보험사기 대응"},"jobs":["보상·손해사정","상품개발"],"basic":true,"summary":"작년 보험사기 적발 금액이 1조 1,571억 원으로 역대 최고였어. 걸린 사람 수는 줄었는데, 병원이랑 브로커가 낀 큰 사기가 늘어서 금액은 오히려 커졌대.","p0":"금감원 발표에 따르면 2025년 보험사기 적발액은 **1조 1,571억 원**으로 역대 최대였고, 적발 인원은 10만 5,743명으로 3.0% 줄었어요. **한 건당 규모가 커진** 거예요.","hi":1,"tn":["보험사기","사고내용 조작","실손보험","손해율"]},{"id":"2026-03-30-b1","date":"2026-03-30","tag":"보험사 실적","title":"보험사 순이익 도입 3년 만에 첫 감소, 낙관적 가정이 예실차로 돌아왔다","thread":{"id":"ifrs17","name":"새 회계기준과 보험부채"},"companies":["삼성생명","한화생명","현대해상"],"jobs":["계리","리스크관리"],"basic":true,"summary":"보험사들이 처음에 앞으로 보험금이 적게 나갈 거라고 좋게 예상해서 이익이 커 보였는데, 실제로는 더 많이 나가니까 3년 만에 이익이 처음으로 줄었어. 낙관적인 예상이 청구서로 돌아온 거지.","co":["삼성생명","한화생명","현대해상"],"p0":"금감원에 따르면 2025년 보험사 순이익은 **12조 2,172억 원으로 14.5% 줄어**, 새 회계기준 도입 뒤 처음 감소했어요.","hi":1,"tn":["예실차","손실계약","보험계약마진","계리가정","보험손익"]},{"id":"2026-03-25-b1","date":"2026-03-25","tag":"자동차보험 · 손해율","title":"투자로 벌었는데도 겨우 흑자, 2025년 자동차보험 보험손익 7,080억 원 적자","thread":{"id":"auto-loss","name":"자동차보험 손해율과 보험료"},"jobs":["계리","상품개발","보상·손해사정"],"basic":true,"summary":"작년 자동차보험은 보험 장사로는 7천억 원 넘게 손해였는데, 받은 돈 굴려서 번 돈으로 겨우 흑자를 냈어. 보험료는 계속 내렸고 치료비랑 부품값은 올랐기 때문이야.","p0":"금융감독원에 따르면 2025년 자동차보험 **보험손익은 7,080억 원 적자**였고, 투자손익(34.1% 증가)을 더한 전체 손익은 951억 원으로 83.9% 줄었어요.","hi":1,"tn":["손해율","합산비율","보험손익","투자손익","사업비율"]},{"id":"2026-03-11-b1","date":"2026-03-11","tag":"판매채널","title":"새 수수료 규칙 시행 직전, '25회차 시책'으로 돌아간 영업에 금감원이 경고한 이유","thread":{"id":"sales-channel","name":"판매채널과 수수료"},"jobs":["상품개발","영업·채널"],"basic":true,"summary":"첫해 수수료를 묶는 규칙이 대리점까지 확대되니까, 일부 대리점이 3년째에 수수료를 따로 달라고 했대. 금감원은 규칙 피해 가는 꼼수라고 검사하겠다고 했어.","p0":"금감원은 2026년 보험 부문 감독 업무설명회에서 판매수수료 개편을 앞두고 과도한 설계사 스카우트와 **다른 형태의 수수료 요구**가 이어진다며, 이를 **제도 우회 행위**로 본다고 경고했어요.","hi":1,"tn":["시책","법인보험대리점","1200% 룰","풍선효과"]},{"id":"2026-01-20-b1","date":"2026-01-20","tag":"감독·계리","title":"보험부채 과소평가 막는다, 계리감독 선진화 방안으로 손해율·사업비 가정에 기준선","thread":{"id":"actuarial-supervision","name":"계리감독 강화"},"jobs":["계리","상품개발","리스크관리"],"basic":true,"summary":"보험사마다 앞으로 보험금이 얼마나 나갈지 예상하는 방식이 제각각이고 너무 낙관적이어서, 당국이 '최소 이 정도는 보수적으로 잡고, 근거도 다 적어서 매년 내라'고 기준을 세운 거야.","p0":"2026년 1월 20일 금융위와 금감원은 **보험업권 계리감독 선진화 방안**을 내놨어요. 최선추정을 대원칙으로, 중립성·보수성·비교가능성을 세부 원칙으로 삼아요.","hi":1,"tn":["계리가정","최선추정부채","사업비","목표손해율","계리가정보고서"]},{"id":"2026-01-13-b1","date":"2026-01-13","tag":"자동차보험 · 손해율","title":"4년 내리고 드디어 인상, 자동차보험료 5년 만에 1.3~1.4% 오른다","thread":{"id":"auto-loss","name":"자동차보험 손해율과 보험료"},"companies":["삼성화재","현대해상","DB손해보험","KB손해보험","메리츠화재"],"jobs":["상품개발","계리"],"basic":true,"summary":"자동차보험료를 4년 동안 계속 내렸더니 보험사가 버티기 힘들어져서, 5년 만에 1%대로 올렸어. 근데 원가도 계속 올라서 이걸로도 적자를 다 메우긴 어렵대.","co":["삼성화재","DB손해보험","현대해상","KB손해보험","메리츠화재"],"p0":"2026년 1월 대형 손보사들이 자동차보험료를 **1.3~1.4% 올리기로** 했어요. 2021년 이후 처음인 인상으로, 2월 중순부터 새 계약에 적용돼요.","hi":1,"tn":["손해율","정비수가","손익분기선"]},{"id":"2026-01-06-b1","date":"2026-01-06","tag":"건전성·자본","title":"잘해서 받은 혜택이 기본자본에선 벌점? 해약환급금준비금 100% 반영 검토","thread":{"id":"kics","name":"지급여력제도(킥스)"},"jobs":["리스크관리","계리"],"basic":true,"summary":"체력 점수가 좋은 보험사한테 '적립금 덜 쌓아도 돼'라는 혜택을 줬는데, 진짜 자기 돈 점수를 따로 매기니까 그 혜택이 오히려 감점이 되는 이상한 일이 생겼어. 그래서 당국이 계산 방식을 고치려는 거야.","p0":"해약환급금준비금은 새 회계기준과 함께 생긴 계정으로, 시가로 잰 부채가 **해약환급금보다 적으면 그 차이를 쌓아** 부채를 보수적으로 유지해요. 법정준비금이라 배당가능이익에서 빠져요.","hi":1,"tn":["해약환급금준비금","해약환급금","기본자본","보완자본","지급여력비율"]},{"id":"2025-12-15-b1","date":"2025-12-15","tag":"고령화·노후","title":"치료에서 돌봄으로, 요양사업에 뛰어든 보험사들이 막힌 곳","thread":{"id":"aging","name":"고령화와 보험"},"companies":["KB라이프","신한라이프","삼성생명","하나생명","동양생명","ABL생명"],"jobs":["상품개발","리스크관리"],"basic":true,"summary":"나이 든 사람이 많아지니까 보험사들이 요양원 같은 돌봄 사업에 뛰어들고 있어. 그런데 요양원 땅이랑 건물을 직접 가져야 하는 규제 때문에 쉽지 않대.","co":["삼성생명","신한라이프","KB라이프","동양생명","ABL생명","하나생명"],"p0":"초고령사회로 요양·돌봄 수요가 커지면서 보험사들이 **치료에서 돌봄으로** 사업을 넓히고 있어요. KB라이프(골든라이프케어), 신한라이프(신한라이프케어), 삼성생명(삼성노블라이프)이 요양시설이나 시니어타운을 운영해요.","hi":1,"tn":["초고령사회","장기요양","시니어타운","보험계약마진"]},{"id":"2025-10-29-b1","date":"2025-10-29","tag":"보험사기","title":"보험사기 광고글 수백 건에서 월 10건으로, 이제 설계사 가담을 막는다","thread":{"id":"fraud","name":"보험사기 대응"},"jobs":["보상·손해사정","리스크관리"],"basic":true,"summary":"보험사기 광고 금지법이 생긴 뒤로 광고글이 수백 건에서 한 달 10건 정도로 줄었대. 이제는 설계사가 사기에 끼는 걸 막는 게 다음 숙제래.","p0":"금융위원회가 보건복지부, 경찰청, 금감원, 건강보험공단 등과 **보험조사협의회**를 열고 개정 특별법의 성과를 점검했어요. 보험사기 광고글은 **월평균 10건 안팎**으로 줄었어요.","hi":1,"tn":["보험사기","알선·유인","내부통제","할증"]},{"id":"2025-10-22-b1","date":"2025-10-22","tag":"고령화·노후","title":"죽은 뒤 받던 사망보험금, 살아서 연금처럼 받는다","thread":{"id":"aging","name":"고령화와 보험"},"companies":["삼성생명","한화생명","교보생명","신한라이프","KB라이프"],"jobs":["계리","상품개발"],"basic":true,"summary":"죽은 다음에 가족이 받던 종신보험 사망보험금을, 55세 넘으면 살아 있을 때 연금처럼 나눠 받을 수 있게 됐어. 노후 생활비로 쓰라는 거지.","co":["삼성생명","한화생명","교보생명","신한라이프","KB라이프"],"p0":"10월 30일부터 삼성생명, 한화생명, 교보생명, 신한라이프, KB라이프가 **사망보험금 유동화** 상품을 내놨어요. 사망 뒤 유족이 받던 종신보험 사망보험금을 **본인이 살아 있을 때 연금처럼** 나눠 받는 거예요.","hi":1,"tn":["종신보험","사망보험금 유동화","톤틴보험","예정이율"]},{"id":"2025-07-29-b1","date":"2025-07-29","tag":"금리·보험료","title":"예정이율 0.25%p 내리면 보험료는 최대 10%, 삼성화재도 8월 인상 합류","thread":{"id":"rates","name":"금리와 보험료"},"companies":["삼성화재","DB손해보험","KB손해보험"],"jobs":["상품개발","계리"],"basic":true,"summary":"보험사는 우리가 낸 보험료를 굴려서 돈을 버는데, 금리가 내려가서 덜 벌게 되니까 그만큼 보험료를 올린 거야. 0.25%p 차이로 보험료가 최대 10%나 오를 수 있어.","co":["삼성화재","DB손해보험","KB손해보험"],"p0":"국내 최대 손해보험사인 삼성화재가 2025년 8월 1일부터 장기보장성보험 등의 **예정이율을 0.25%p 낮춰** 보험료를 최대 10% 올리기로 했어요. DB손해보험이 7월 14일 먼저 발표했고, KB손해보험도 8월 인하에 나섰어요.","hi":1,"tn":["예정이율","공시이율","역마진","투자손익"]},{"id":"2025-06-11-b1","date":"2025-06-11","tag":"건전성·자본","title":"보험사 지급여력비율 권고 기준 150%에서 130%로, 24년 만에 낮춘 이유","thread":{"id":"kics","name":"지급여력제도(킥스)"},"jobs":["리스크관리","계리"],"basic":true,"summary":"보험사 체력 점수 합격선을 150점에서 130점으로 낮춘 거야. 대신 빌린 돈으로 채운 점수 말고 진짜 자기 돈으로 된 점수를 따로 보겠다고 했어.","p0":"금융위원회는 2025년 6월 11일 보험사 지급여력비율(킥스) **권고 기준을 150%에서 130%로** 낮추는 규정 개정을 의결하고 바로 시행했어요.","hi":1,"tn":["지급여력비율","기본자본","보완자본","후순위채","스트레스 테스트"]},{"id":"2025-06-01-b1","date":"2025-06-01","tag":"판매채널","title":"설계사 수수료, 한 번에 말고 7년에 나눠 받는다","thread":{"id":"sales-channel","name":"판매채널과 수수료"},"jobs":["계리","영업·채널"],"basic":true,"summary":"설계사 수수료를 처음에 한 번에 몰아주던 걸 앞으로는 최대 7년에 나눠 주기로 했어. 계약을 오래 지켜줘야 설계사가 돈을 더 받게 바꾼 거지.","p0":"금융위원회가 판매수수료 개편 세부방안을 확정했어요. 수수료 **분급 기간을 최대 3년에서 7년으로** 늘리고, 계약을 유지하는 동안 매월 주는 **유지관리 수수료**를 새로 만들어요.","hi":1,"tn":["분급","유지관리 수수료","1200% 룰","사업비","해지율"]},{"id":"2025-04-01-b1","date":"2025-04-01","tag":"실손보험","title":"가벼운 비급여는 절반을 내가, 실손보험 개혁방안으로 5세대 윤곽 확정","thread":{"id":"silson-reform","name":"실손보험 개편"},"jobs":["상품개발","계리"],"basic":true,"summary":"5세대 실손은 큰 병 보장은 그대로 두고, 도수치료 같은 가벼운 비급여는 내가 절반을 내게 바꾼 거야. 대신 보험료가 싸지는 거지.","p0":"2025년 4월 1일 금융위원회는 **실손보험 개혁방안**을 발표했어요. 비급여를 **중증(특약1)과 비중증(특약2)**으로 나눠, 중증은 4세대 수준을 지키고 비중증은 보장을 줄였어요.","hi":1,"tn":["실손보험","비급여","자기부담률","계약 재매입","보상한도"]},{"id":"2025-01-22-b1","date":"2025-01-22","tag":"자동차보험 · 손해율","title":"손해율 93%인데 보험료는 또 내린다? 자동차보험 4년 연속 인하","thread":{"id":"auto-loss","name":"자동차보험 손해율과 보험료"},"companies":["메리츠화재","삼성화재","DB손해보험","현대해상","KB손해보험"],"jobs":["계리","상품개발"],"basic":true,"summary":"자동차보험은 손해율이 90% 넘게 올라서 보험사는 올리고 싶었는데, 모두가 드는 보험이라 정부가 물가 생각해서 내려달라고 했거든. 그래서 4년째 또 조금 내렸어.","co":["삼성화재","DB손해보험","현대해상","KB손해보험","메리츠화재"],"p0":"2025년 1월 메리츠화재가 개인용 자동차보험료 **1% 인하**를 먼저 발표했고, 대형사들도 0.5~1.0% 인하를 검토했어요. 2022년부터 **4년 연속 인하**예요.","hi":1,"tn":["손해율","정비수가","상생금융","의무보험"]},{"id":"2024-11-28-b1","date":"2024-11-28","tag":"고령화·노후","title":"간병인 플랫폼으로 불러도 보험금 받을까? 간병보험 약관이 바뀐 이유","thread":{"id":"aging","name":"고령화와 보험"},"jobs":["상품개발","보상·손해사정"],"basic":true,"summary":"간병보험이 인기라 분쟁이 늘었는데, 앞으로는 간병인 플랫폼으로 부른 간병인도 인정하는 대신 진짜로 간병을 받았을 때만 보험금을 주게 약관을 바꾼대.","p0":"금감원은 제7차 공정금융추진위원회에서 보험사마다 다르거나 모호한 **간병보험 약관을 연말까지 고치기로** 했어요.","hi":1,"tn":["간병보험","도덕적 해이","약관","역선택"]},{"id":"2024-11-11-b1","date":"2024-11-11","tag":"감독·계리","title":"무·저해지보험 해지율, 완납 시점엔 0%로 수렴하라는 원칙모형과 나흘 만의 '사실상 의무화'","thread":{"id":"actuarial-supervision","name":"계리감독 강화"},"jobs":["계리","상품개발"],"basic":true,"summary":"보험료가 싼 대신 중간에 깨면 돈을 거의 못 돌려받는 보험이 있는데, 보험사들이 '사람들이 많이 깰 거야'라고 가정해서 장부가 좋아 보였어. 당국이 '다 낸 사람은 안 깬다고 보고 계산해'라고 못 박은 거야.","p0":"금융당국은 2024년 11월 7일 무·저해지보험 해지율 가정에서 **완납 시점 해지율이 0%에 수렴하는 원칙모형**을 담은 가이드라인을 내고, 그해 말 결산부터 적용하기로 했어요.","hi":1,"tn":["무·저해지보험","해지율","완납","원칙모형","지급여력비율"]},{"id":"2024-10-14-b1","date":"2024-10-14","tag":"금리·보험료","title":"3년 2개월 만의 금리 인하, 대출자는 웃는데 보험사는 왜 긴장할까","thread":{"id":"rates","name":"금리와 보험료"},"companies":["한화생명","동양생명","흥국화재","KB손해보험"],"jobs":["계리","리스크관리"],"basic":true,"summary":"금리가 내리면 대출 이자는 줄지만, 보험사는 먼 미래에 줄 돈의 현재 가치가 커져서 빚이 늘어난 것처럼 돼. 그래서 자본이 줄고 결국 보험료도 오르기 쉬워.","co":["한화생명","동양생명","KB손해보험","흥국화재"],"p0":"2024년 10월 한국은행이 기준금리를 **0.25%p 내리면서** 3년 2개월 만에 금리 방향이 바뀌었어요. 새 회계기준 도입 뒤 처음 맞는 금리 인하였어요.","hi":1,"tn":["지급여력비율","최선추정부채","투자손익","후순위채","듀레이션","예정이율"]},{"id":"2024-08-13-b1","date":"2024-08-13","tag":"보험사기","title":"보험사기 '알선'만 해도 처벌, 8년 만에 바뀐 보험사기방지법","thread":{"id":"fraud","name":"보험사기 대응"},"jobs":["보상·손해사정","상품개발"],"basic":true,"summary":"보험사기를 직접 안 쳐도 '보험으로 공짜 시술' 같은 광고로 사람을 끌어들이기만 해도 최대 징역 10년까지 받게 법이 바뀌었어. 2016년 법이 생긴 뒤 8년 만에 처음 고친 거야.","p0":"2024년 8월 14일 개정 보험사기방지 특별법이 시행됐어요. 2016년 제정 뒤 **8년 만의 첫 개정**으로, 보험사기를 **알선·유인·광고하는 행위**를 금지했어요.","hi":1,"tn":["보험사기","알선·유인","손해율","할증"]},{"id":"2024-03-26-b1","date":"2024-03-26","tag":"보험사 실적","title":"새 회계기준 첫해 보험사 순이익 45.5% 급증, 정말 장사를 잘한 걸까","thread":{"id":"ifrs17","name":"새 회계기준과 보험부채"},"jobs":["계리","리스크관리"],"basic":true,"summary":"보험사들이 보험은 덜 팔았는데 돈은 45%나 더 벌었다고 나왔어. 근데 이건 장사를 잘해서라기보다 장부 쓰는 방식이 바뀐 효과가 컸던 거야.","p0":"금감원에 따르면 2023년 보험사 순이익은 **13조 3,578억 원으로 45.5% 늘었어요.** 손해보험사가 8조 2,626억 원(+50.9%), 생명보험사가 5조 952억 원(+37.6%)이었어요.","hi":1,"tn":["보험계약마진","새 국제회계기준","예실차","보장성 보험"]},{"id":"2023-05-31-b1","date":"2023-05-31","tag":"감독·계리","title":"실적 착시 막아라, 당국 첫 계리가정 가이드라인에 보험계약마진 '조 단위' 축소 우려","thread":{"id":"actuarial-supervision","name":"계리감독 강화"},"jobs":["계리","상품개발"],"basic":true,"summary":"보험사들이 '실손 적자가 몇 년 안에 금방 좋아질 거야'라고 좋게 예상해서 이익이 커 보였거든. 그래서 당국이 최소 15년은 보고 계산하라고 기준을 정해준 거야.","p0":"2023년 5월 31일 금융위와 금감원은 새 회계기준 도입 뒤 실적이 크게 부풀어 보인다는 '착시' 논란에 **첫 계리가정 가이드라인**을 내놨어요.","hi":1,"tn":["계리가정","최선추정부채","보험계약마진","목표손해율","무·저해지보험"]},{"id":"2022-12-29-b1","date":"2022-12-29","tag":"회계제도","title":"보험부채를 '지금 값'으로 다시 잰다, 새 국제회계기준 2023년 1월 시행 확정","thread":{"id":"ifrs17","name":"새 회계기준과 보험부채"},"jobs":["계리","상품개발","리스크관리"],"basic":true,"summary":"보험사가 앞으로 줄 보험금을 장부에 적을 때, 예전엔 처음 정한 값 그대로 뒀다면 이제는 지금 시점 기준으로 계속 다시 계산하게 된 거야. 그래서 그 계산에 쓰는 예상이 엄청 중요해졌어.","p0":"2022년 12월 28일 보험업법 개정안이 국회를 통과해, **2023년 1월 1일부터 새 국제회계기준**이 개정 법령과 함께 시행됐어요.","hi":1,"tn":["새 국제회계기준","시가평가","발생주의","조건부자본증권","선임계리사"]},{"id":"2022-12-28-b1","date":"2022-12-28","tag":"자동차보험 · 손해율","title":"목 삐끗하고 몇 달 치료? 2023년부터 경상환자도 내 과실만큼은 내 보험으로","thread":{"id":"auto-loss","name":"자동차보험 손해율과 보험료"},"jobs":["상품개발","보상·손해사정"],"basic":true,"summary":"예전엔 차 사고 나서 목 좀 삐끗해도 상대 보험사가 치료비를 다 내줘서 몇 달씩 치료받는 사람이 많았거든. 2023년부터는 내 잘못만큼은 내 보험으로 내고, 4주 넘게 치료하려면 진단서가 있어야 해.","p0":"2023년 1월 1일 사고부터 염좌·타박상 같은 **경상환자(상해등급 12~14급)**는 책임보험 한도를 넘는 치료비 가운데 본인 과실만큼을 본인 보험으로 처리해요.","hi":1,"tn":["손해율","과실책임주의","경상환자","과잉진료"]},{"id":"2022-12-05-b1","date":"2022-12-05","tag":"건전성·자본","title":"보험사 체력검사가 바뀐다, 2023년 시가 기반 지급여력제도(킥스) 시행","thread":{"id":"kics","name":"지급여력제도(킥스)"},"jobs":["리스크관리","계리"],"basic":true,"summary":"보험사가 큰일이 터져도 보험금을 줄 수 있는지 재는 체력검사가 있는데, 2023년부터 그걸 지금 시세 기준으로 더 꼼꼼하게 재기로 한 거야. 오래 사는 위험이나 해지가 몰리는 위험도 새로 재고.","p0":"금감원은 2023년부터 자산과 부채를 **공정가치로 평가하는 새 지급여력제도(킥스)**를 시행한다고 밝혔어요. 국제 자본규제와 기준을 맞춘 제도예요.","hi":1,"tn":["지급여력비율","가용자본","요구자본","기본자본","보완자본"]},{"id":"2022-11-07-b1","date":"2022-11-07","tag":"금리·보험료","title":"은행 예금에 맞선 연 5%대 저축보험, 11년 만에 돌아온 고금리 경쟁","thread":{"id":"rates","name":"금리와 보험료"},"companies":["한화생명","흥국생명","동양생명","ABL생명"],"jobs":["상품개발","계리","영업·채널"],"basic":true,"summary":"2022년에 은행 금리가 확 오르니까 보험사들도 손님 뺏길까 봐 저축보험 이자를 5%대까지 올렸어. 근데 수수료 같은 걸 떼고 나면 실제 이자는 그보다 낮아.","co":["한화생명","동양생명","ABL생명","흥국생명"],"p0":"2022년 기준금리가 오르면서 은행 예·적금 금리가 크게 뛰자, 생명보험사들은 고객 이탈을 막으려고 **저축성보험 금리를 경쟁적으로 올렸어요.**","hi":1,"tn":["저축성보험","사업비","역마진","방카슈랑스"]},{"id":"2021-04-29-b1","date":"2021-04-29","tag":"판매채널","title":"손보사가 판매하는 데 쓴 돈 2조 7,638억 원, 역대 최대가 된 이유","thread":{"id":"sales-channel","name":"판매채널과 수수료"},"companies":["현대해상","DB손해보험","삼성화재"],"jobs":["상품개발","영업·채널"],"basic":true,"summary":"보험사들이 설계사랑 대리점한테 주는 판매 수수료가 2020년에 2조 7천억 원 넘게 역대 최고였어. 서로 설계사 데려가려고 경쟁하다 보니 그렇게 된 거래.","co":["삼성화재","DB손해보험","현대해상"],"p0":"2020년 주요 손보사 10곳의 지급수수료는 **2조 7,638억 원**으로 역대 최고였어요. 이 가운데 대리점수수료가 2조 4,819억 원으로 대부분이에요.","hi":1,"tn":["사업비","법인보험대리점","1200% 룰","전속 설계사"]},{"id":"2020-12-09-b1","date":"2020-12-09","tag":"실손보험","title":"병원 많이 가면 보험료도 더 낸다, 4세대 실손 '비급여 차등제' 확정","thread":{"id":"silson-reform","name":"실손보험 개편"},"jobs":["상품개발","계리","언더라이팅"],"basic":true,"summary":"실손보험은 병원 많이 가는 소수 때문에 모두의 보험료가 올랐거든. 그래서 4세대부터는 비급여를 많이 쓰면 보험료를 더 내고 안 쓰면 깎아주는 방식으로 바꾼 거야.","p0":"2020년 12월 9일 금융위원회는 2021년 7월 출시할 **4세대 실손보험**의 구조를 확정했어요. 급여는 주계약, 비급여는 특약으로 나누고 자기부담률을 **급여 20%, 비급여 30%**로 올렸어요.","hi":1,"tn":["실손보험","비급여","자기부담률","재가입 주기","보험료 차등제","산정특례"]}];
window.GLOSS_DATA=[["부지급률","보험금 청구 건수 가운데 보험금을 지급하지 않은 건수가 차지하는 비율이에요.",["2026-11-05-1"]],["실손보험","실제로 쓴 병원비 가운데 본인이 낸 돈을 약관에 따라 보상해주는 보험이에요. 가입 시기에 따라 1세대부터 5세대까지 나뉘어요.",["2026-11-05-1","2026-10-30-2","2026-05-05-b1","2026-03-31-b1","2025-04-01-b1","2020-12-09-b1"]],["비급여","건강보험이 보장하지 않아 환자가 전부 내는 진료예요. 도수치료나 일부 주사제 등이 있어요.",["2026-11-05-1","2026-10-30-2","2026-05-05-b1","2025-04-01-b1","2020-12-09-b1"]],["자기부담률","병원비 가운데 보험이 보상하지 않고 가입자가 직접 내야 하는 비율이에요.",["2026-11-05-1","2026-10-30-2","2025-04-01-b1","2020-12-09-b1"]],["망분리","업무용 내부 전산망과 외부 인터넷망을 나눠, 바깥에서 내부 전산으로 바로 들어오지 못하게 하는 보안 방식이에요.",["2026-11-05-2"]],["내부통제","회사가 직원과 판매조직의 잘못된 행동을 미리 막고 점검하는 관리 체계예요.",["2026-11-05-2","2026-11-04-2","2025-10-29-b1"]],["운영위험","사람, 시스템, 내부 절차의 잘못이나 외부 사건 때문에 생기는 손실 위험이에요.",["2026-11-05-2","2026-11-04-2"]],["현장점검","금융당국이 회사에 직접 나가 특정 문제를 확인하는 일이에요. 문제가 크면 정식 검사로 바뀌기도 해요.",["2026-11-05-2","2026-11-04-2"]],["1200% 룰","보험사가 설계사에게 계약 첫해에 줄 수 있는 수수료를 월 보험료의 12배 이내로 묶는 규칙이에요.",["2026-11-05-3","2026-11-04-6","2026-10-15-1","2026-10-08-1","2026-03-11-b1","2025-06-01-b1","2021-04-29-b1"]],["분급","수수료를 한 번에 주지 않고 여러 해에 걸쳐 나눠 주는 방식이에요.",["2026-11-05-3","2026-11-04-6","2025-06-01-b1"]],["법인보험대리점","특정 보험사에 소속되지 않고 여러 보험사 상품을 함께 파는 판매 회사예요.",["2026-11-05-3","2026-11-04-1","2026-11-04-6","2026-10-08-1","2026-10-01-1","2026-03-11-b1","2021-04-29-b1"]],["기저효과","비교 기준이 되는 시점의 숫자가 유난히 높거나 낮아서, 실제보다 크게 바뀐 것처럼 보이는 현상이에요.",["2026-11-05-3","2026-10-29-1"]],["투자한도","보험업법이 보험사가 대주주나 자회사의 채권·주식을 들고 있을 수 있는 금액에 거는 상한이에요. 자기자본의 60%와 총자산의 3% 중 적은 금액이에요.",["2026-11-05-4"]],["지급여력비율","보험사가 위험이 닥쳐도 보험금을 줄 수 있는 능력을 보여주는 건전성 지표예요. 지금 제도의 이름을 따 킥스 비율이라고도 불러요.",["2026-11-05-4","2026-10-31-4","2026-10-30-3","2026-10-20-3","2026-10-15-3","2026-10-08-3","2026-01-06-b1","2025-06-11-b1","2024-11-11-b1","2024-10-14-b1","2022-12-05-b1"]],["투자손익","받은 보험료를 채권, 주식 등으로 굴려서 번 이익이에요. 금리와 시장 상황에 따라 크게 흔들려요.",["2026-11-05-4","2026-10-31-2","2026-10-30-3","2026-10-18-2","2026-03-25-b1","2025-07-29-b1","2024-10-14-b1"]],["계리가정보고서","보험사가 계리가정의 체계, 산출 근거와 결과, 내부통제를 담아 금감원에 내는 보고서예요.",["2026-11-04-1","2026-01-20-b1"]],["계리가정","보험료와 보험부채를 계산할 때 쓰는 예상 손해율, 해지율, 사업비율 같은 전제예요.",["2026-11-04-1","2026-10-31-2","2026-10-30-1","2026-10-12-1","2026-03-30-b1","2026-01-20-b1","2023-05-31-b1"]],["듀레이션 갭","자산과 부채의 듀레이션 차이예요. 클수록 금리가 움직일 때 순자산 가치가 크게 흔들려요.",["2026-11-04-1"]],["경영실태평가","금융당국이 보험사의 경영 상태를 자본, 위험, 경영관리 같은 부문별로 평가하는 제도예요.",["2026-11-04-1"]],["비상위험준비금","큰 재해처럼 드물지만 큰 손실에 대비해 보험료의 일부를 따로 쌓아두는 준비금이에요.",["2026-11-04-1"]],["법정손해배상","피해자가 실제 손해액을 증명하지 않아도 법이 정한 범위에서 배상을 청구할 수 있는 제도예요.",["2026-11-04-2"]],["인허가","회사가 영업을 하거나 상품을 팔기 전에 감독당국에서 받아야 하는 허락이에요.",["2026-11-04-3"]],["감독당국","금융회사가 법과 규칙을 지키는지 살피고 관리하는 기관이에요. 우리나라는 금융위원회와 금융감독원이에요.",["2026-11-04-3"]],["위험률","사고나 질병이 생길 확률로, 보험료를 계산하는 기초가 돼요.",["2026-11-04-3"]],["사망보험금 유동화","종신보험의 사망보험금 일부를 가입자가 살아 있을 때 연금처럼 나눠 받는 제도예요.",["2026-11-04-4","2025-10-22-b1"]],["종신보험","평생 보장하고, 언제 사망하든 정해진 사망보험금을 유족에게 주는 생명보험이에요.",["2026-11-04-4","2026-11-03-2","2026-10-21-2","2026-10-14-1","2025-10-22-b1"]],["해약환급금","계약자가 보험을 중간에 해지할 때 돌려받는 돈이에요.",["2026-11-04-4","2026-11-03-2","2026-10-20-4","2026-10-15-1","2026-01-06-b1"]],["초고령사회","65세 이상 인구가 전체의 20% 이상인 사회예요.",["2026-11-04-4","2025-12-15-b1"]],["현물급부","보험금을 현금으로 주는 대신 서비스를 직접 제공하는 방식이에요.",["2026-11-04-5"]],["운전자보험","운전 중 사고로 생기는 형사 절차 비용과 벌금, 변호사 선임 비용 등을 보장하는 보험이에요.",["2026-11-04-5"]],["도덕적 해이","보험에 든 뒤 조심을 덜 하거나 보장을 필요 이상으로 이용하려는 행동이에요.",["2026-11-04-5","2024-11-28-b1"]],["시책","보험사가 판매를 늘리려고 기본 수수료 외에 설계사나 대리점에 추가로 주는 보상이에요.",["2026-11-04-6","2026-10-15-1","2026-03-11-b1"]],["부당승환","소비자에게 불리한데도 기존 보험을 해지시키고 비슷한 새 보험으로 갈아타게 하는 영업이에요.",["2026-11-04-6","2026-10-21-2","2026-10-08-1"]],["예금보험료율","금융회사가 예금보험공사에 내는 예금보험료를 정하는 비율이에요.",["2026-11-03-1","2026-10-19-1"]],["예금자보호한도","금융회사가 문을 닫아도 예금보험공사가 1인당 돌려주는 최대 금액이에요. 2025년 9월부터 1억 원이에요.",["2026-11-03-1"]],["예금보험기금","금융회사가 낸 예금보험료로 쌓아, 금융회사가 망했을 때 예금자에게 돈을 돌려주는 데 쓰는 기금이에요.",["2026-11-03-1","2026-10-20-2","2026-10-19-1"]],["사업비","모집수수료 같은 계약체결비와 계약을 관리하는 유지비 등 보험을 운영하는 데 드는 비용이에요.",["2026-11-03-1","2026-10-30-1","2026-01-20-b1","2025-06-01-b1","2022-11-07-b1","2021-04-29-b1"]],["해피콜","가입 뒤 보험사가 계약자에게 연락해 설명을 제대로 들었는지 확인하는 절차예요.",["2026-11-03-2"]],["특약 만기","주계약에 덧붙인 특약의 보장이 끝나는 시점이에요. 주계약과 다를 수 있어요.",["2026-11-03-2"]],["고지의무","보험에 들 때 건강 상태 같은 중요한 사실을 보험사에 사실대로 알려야 하는 의무예요.",["2026-11-03-2","2026-10-31-3"]],["700종신","가입 7년 뒤 해약환급금이 낸 보험료의 100% 수준이 되도록 설계한 종신보험을 업계에서 부르는 말이에요.",["2026-11-03-3","2026-10-21-1","2026-10-21-2"]],["건강종신","암 같은 중대질병을 진단받으면 보험금을 미리 주고, 사망보장도 함께 유지하는 종신보험이에요.",["2026-11-03-3"]],["인출형 종신보험","살아 있는 동안 납입보험료 범위에서 돈을 꺼내 쓰면서 사망보장을 유지하는 종신보험이에요.",["2026-11-03-3","2026-10-21-2"]],["해지율","보험계약이 일정 기간 안에 중도 해지되는 비율이에요. 보험료와 보험부채 계산의 핵심 가정이에요.",["2026-11-03-3","2026-10-18-1","2026-10-14-1","2025-06-01-b1","2024-11-11-b1"]],["보험계약마진","보험계약에서 앞으로 나눠서 이익으로 인식할, 아직 실현되지 않은 이익이에요.",["2026-11-03-3","2026-10-31-1","2026-10-30-1","2026-10-30-3","2026-10-20-3","2026-10-18-1","2026-10-13-1","2026-10-12-1","2026-03-30-b1","2025-12-15-b1","2024-03-26-b1","2023-05-31-b1"]],["가입경력 인정","본인 명의가 아니어도 실제 운전한 기간을 자동차보험 가입경력으로 쳐주는 제도예요. 직접 신청해야 해요.",["2026-11-02-1"]],["종피보험자","주된 피보험자 외에 같은 자동차보험으로 함께 보장받도록 이름을 올린 사람이에요.",["2026-11-02-1"]],["운전자 한정 특약","운전할 수 있는 사람의 범위를 좁히는 대신 보험료를 깎아주는 특약이에요.",["2026-11-02-1"]],["할인특약","정해진 조건을 지키면 보험료를 깎아주는 특약이에요. 마일리지, 대중교통 이용, 걸음 수 할인 등이 있어요.",["2026-11-02-1"]],["퇴직연금","회사가 근로자의 퇴직급여를 금융회사에 맡겨 쌓아두었다가, 퇴직 뒤 연금이나 일시금으로 주는 제도예요.",["2026-11-02-2"]],["기금형 퇴직연금","회사 밖에 별도 기금을 두고, 전문 수탁법인이 근로자를 대신해 퇴직연금을 운용하는 방식이에요.",["2026-11-02-2"]],["사외적립","퇴직급여를 회사 안이 아니라 금융회사 같은 바깥에 쌓아두는 것이에요. 회사가 어려워져도 근로자 몫을 지킬 수 있어요.",["2026-11-02-2"]],["수탁자 책임","남의 돈을 맡아 굴리는 사람이 맡긴 사람의 이익을 가장 먼저 생각해야 하는 책임이에요.",["2026-11-02-2"]],["시민안전보험","지자체가 보험료를 내고, 그 지역에 주민등록이 된 사람을 자동으로 가입시켜 재난과 사고를 보장하는 보험이에요.",["2026-11-01-1"]],["소멸시효","권리를 일정 기간 쓰지 않으면 그 권리가 없어지는 제도예요. 보험금 청구권은 원칙적으로 3년이에요.",["2026-11-01-1"]],["연간 총 보상한도","한 해 동안 보험사가 지급할 보험금의 최대 합계예요. 한도를 다 쓰면 그해 지급이 끝날 수 있어요.",["2026-11-01-1"]],["손해율","보험사가 받은 보험료 가운데 보험금으로 나간 돈의 비율이에요. 높을수록 보험사 수익이 나빠져요.",["2026-11-01-1","2026-10-31-3","2026-10-29-1","2026-10-20-2","2026-10-12-1","2026-10-08-2","2026-03-31-b1","2026-03-25-b1","2026-01-13-b1","2025-01-22-b1","2024-08-13-b1","2022-12-28-b1"]],["방카슈랑스","은행 창구에서 보험상품을 파는 판매 방식이에요.",["2026-10-31-1","2022-11-07-b1"]],["25% 룰","은행 같은 금융기관보험대리점이 한 보험사 상품을 신규 모집액의 25%를 넘겨 팔지 못하게 하는 규제예요.",["2026-10-31-1"]],["농·축협 판매 특례","자산 2조 원 미만 지역 농·축협이 25% 규제를 유예받아 농협보험 상품만 팔 수 있게 한 예외예요. 2012년에 생겨 두 번 연장됐어요.",["2026-10-31-1"]],["손실계약","앞으로 받을 보험료보다 나갈 보험금과 비용이 더 커서, 처음부터 손실이 예상되는 보험계약이에요.",["2026-10-31-1","2026-03-30-b1"]],["이익 기여도","금융지주 전체 순이익 가운데 특정 계열사가 벌어온 몫의 비율이에요. 손실을 내면 마이너스가 돼요.",["2026-10-31-2"]],["감가상각비","전산 시스템이나 건물처럼 오래 쓰는 자산에 든 돈을 쓰는 기간에 나눠 비용으로 잡는 금액이에요.",["2026-10-31-2"]],["보험손익","보험 영업에서 남긴 이익이에요. 받은 보험료에 비해 보험금과 비용을 얼마나 잘 관리했는지 보여줘요.",["2026-10-31-2","2026-10-30-3","2026-10-18-2","2026-03-30-b1","2026-03-25-b1"]],["보험사기","사고를 꾸미거나 피해를 부풀려 보험금을 부당하게 받는 행위예요.",["2026-10-31-3","2026-03-31-b1","2025-10-29-b1","2024-08-13-b1"]],["등록취소","설계사나 손해사정사의 등록을 없애 더 이상 그 일을 할 수 없게 하는 무거운 처분이에요.",["2026-10-31-3"]],["손해사정사","사고가 났을 때 손해액을 조사하고 보험금이 얼마인지 산정하는 전문가예요.",["2026-10-31-3"]],["생산적 금융","부동산이나 단순 대출보다 첨단산업, 사회기반시설처럼 실물경제 성장에 돈이 흘러가게 하는 금융이에요.",["2026-10-31-4"]],["신용생명보험","대출받은 사람이 사망하는 등 사고가 나면 남은 빚을 보험금으로 갚아주는 보험이에요.",["2026-10-31-4"]],["듀레이션","돈이 들어오고 나가는 시점의 평균 만기로, 금리가 변할 때 가치가 얼마나 민감하게 움직이는지 보여줘요.",["2026-10-31-4","2026-10-04-1","2024-10-14-b1"]],["특화보험사","일반 보험사가 잘 다루지 않는 특정 분야의 위험을 전문으로 보장하는 보험사예요.",["2026-10-31-5"]],["배당성향","순이익 가운데 주주에게 배당으로 나눠준 돈의 비율이에요.",["2026-10-31-5"]],["자본 효율성","회사가 쓴 자본에 비해 이익을 얼마나 많이 내는지를 말해요.",["2026-10-31-5"]],["별도 기준","자회사 실적을 합치지 않고 회사 하나만의 실적을 본 기준이에요. 자회사까지 합치면 연결 기준이에요.",["2026-10-31-5"]],["최선추정부채","앞으로 나갈 보험금과 비용, 들어올 보험료를 가장 그럴듯하게 추정해 현재 가치로 바꾼 보험부채예요.",["2026-10-30-1","2026-01-20-b1","2024-10-14-b1","2023-05-31-b1"]],["예실차","가정으로 예상한 값과 실제로 일어난 값의 차이예요. 차이가 크면 가정을 다시 봐야 한다는 신호예요.",["2026-10-30-1","2026-03-30-b1","2024-03-26-b1"]],["목표손해율","보험료를 조정해서 도달하려는 손해율이에요. 손실계약은 보통 100%를 기준으로 해요.",["2026-10-30-1","2026-10-12-1","2026-01-20-b1","2023-05-31-b1"]],["역선택","자기 위험을 보험사보다 잘 아는 가입자 가운데 위험이 높은 사람일수록 보험에 들거나 남으려 해서, 보험 집단의 위험이 높아지는 현상이에요.",["2026-10-30-2","2026-10-20-1","2026-10-06-1","2026-05-05-b1","2024-11-28-b1"]],["재가입 주기","정해진 기간마다 그 시점의 상품 조건으로 다시 가입하게 하는 주기예요. 초기 실손에는 이 주기가 없는 계약이 많아요.",["2026-10-30-2","2026-05-05-b1","2020-12-09-b1"]],["합산비율","손해율에 사업비율(운영비 비율)을 더한 값이에요. 100%를 넘으면 보험 영업만으로는 적자예요.",["2026-10-29-1","2026-03-25-b1"]],["정비수가","자동차 사고 수리를 할 때 정비업체가 보험사에 청구하는 정비 요금의 기준이에요. 오르면 지급 보험금도 늘어나요.",["2026-10-29-1","2026-01-13-b1","2025-01-22-b1"]],["휴업손해","사고로 다쳐 일하지 못한 기간의 소득 손실을 보상하는 항목이에요.",["2026-10-29-1"]],["주가순자산비율","주가를 주당 순자산으로 나눈 값이에요. 1배보다 낮으면 시장이 회사를 장부상 순자산보다 낮게 평가한다는 뜻이에요.",["2026-10-21-1","2026-10-20-3"]],["이익잉여금","회사가 벌어들인 이익 가운데 배당하지 않고 회사 안에 쌓아둔 돈이에요.",["2026-10-21-1","2026-10-18-2"]],["해약환급금준비금","시가로 잰 보험부채가 계약자에게 돌려줄 해약환급금보다 적을 때, 그 차이만큼 따로 쌓는 법정준비금이에요.",["2026-10-21-1","2026-10-18-2","2026-01-06-b1"]],["배당가능이익","회사가 주주에게 배당으로 나눠줄 수 있는 이익의 한도예요.",["2026-10-21-1"]],["정기보험","정해진 기간에만 사망을 보장하는 생명보험이에요. 종신보험보다 보험료가 낮아요.",["2026-10-21-2"]],["납입최고","보험료를 내지 않은 계약자에게 보험사가 일정 기간 안에 내라고 알리는 독촉 절차예요.",["2026-10-20-1"]],["효력상실","보험료를 정해진 기간 안에 내지 않아 보험계약의 효력이 멈춘 상태예요.",["2026-10-20-1","2026-10-18-1"]],["부활","효력이 멈춘 보험계약을 밀린 보험료를 내고 다시 살리는 제도예요.",["2026-10-20-1","2026-10-18-1"]],["의료자문","보험금을 심사할 때 보험사가 의사의 의견을 구하는 절차예요.",["2026-10-20-1"]],["부실금융기관","경영이 크게 나빠져 정상 영업이 어렵다고 금융당국이 지정한 금융회사예요.",["2026-10-20-2"]],["가교보험사","부실 보험사의 계약을 임시로 넘겨받아 관리하면서 새 주인을 찾는 동안 계약자 보호를 이어가는 회사예요.",["2026-10-20-2"]],["계약이전","부실 보험사의 보험계약을 다른 보험사로 넘기는 일이에요.",["2026-10-20-2"]],["자기자본이익률","순이익을 자기자본으로 나눈 비율로, 주주가 맡긴 돈으로 얼마나 벌었는지 보여줘요.",["2026-10-20-3"]],["주주환원","기업이 번 이익을 배당이나 자사주 매입·소각으로 주주에게 돌려주는 일이에요.",["2026-10-20-3"]],["장기요양","혼자 일상생활을 하기 어려운 노인에게 돌봄과 요양 서비스를 제공하는 제도예요.",["2026-10-20-4","2025-12-15-b1"]],["저해약환급금형","납입 중 해지하면 환급금이 적은 대신, 납입을 마치면 환급률이 높아지도록 설계한 상품 형태예요.",["2026-10-20-4"]],["폐렴 중증도 척도","폐렴 환자의 중증 정도를 평가하는 임상 지표예요.",["2026-10-20-4"]],["간편고지","건강 상태에 관한 질문을 줄여 가입 문턱을 낮춘 가입 방식이에요.",["2026-10-20-4"]],["목표기금제","예금보험기금을 어느 규모까지 쌓을지 목표를 정해 두고 그에 맞춰 보험료율을 운영하는 방식이에요.",["2026-10-19-1"]],["국정감사","국회가 해마다 정부와 공공기관이 일을 제대로 하는지 살피는 일이에요.",["2026-10-19-1"]],["보장공백","보험을 해지하거나 효력이 멈춰 아프거나 사고가 나도 보장을 받지 못하는 상태예요.",["2026-10-18-1"]],["기본자본","손실을 막는 힘이 가장 강한 자본이에요. 자본금과 이익잉여금 등이 들어가요.",["2026-10-18-2","2026-10-05-1","2026-01-06-b1","2025-06-11-b1","2022-12-05-b1"]],["차익거래","보험에서 수수료·시책과 해약환급금을 합친 돈이 낸 보험료보다 커서, 일찍 해지할수록 이득이 생기는 상황이에요.",["2026-10-15-1"]],["수수료 환수","계약이 일찍 해지되면 이미 지급한 모집수수료를 다시 돌려받는 것이에요.",["2026-10-15-1","2026-10-08-1"]],["배타적사용권","독창적인 보험상품을 만든 회사에 일정 기간 다른 회사가 비슷한 상품을 팔지 못하게 하는 독점 판매 권리예요. 보험업계의 특허처럼 쓰여요.",["2026-10-15-2","2026-10-06-1"]],["연간 보장한도","한 해 동안 보험금을 받을 수 있는 최대 횟수나 금액이에요.",["2026-10-15-2"]],["한도이연","그해 쓰지 않은 보장한도를 없애지 않고 다음 해로 넘기는 방식이에요.",["2026-10-15-2"]],["담보","보험상품 안에서 어떤 사고나 치료에 보험금을 줄지 정한 보장 단위예요.",["2026-10-15-2"]],["후순위채","회사가 망하면 다른 빚보다 늦게 갚는 채권이에요. 보험사가 보완자본을 늘리려고 많이 발행해요.",["2026-10-15-3","2025-06-11-b1","2024-10-14-b1"]],["보완자본","손실을 막는 데 일부 제한이 있는 자본이에요. 후순위채 같은 자본증권이 대표적이에요.",["2026-10-15-3","2026-10-05-1","2026-01-06-b1","2025-06-11-b1","2022-12-05-b1"]],["조기상환권","만기 전에 발행한 회사가 채권을 먼저 갚을 수 있는 권리예요. 콜옵션이라고도 불러요.",["2026-10-15-3"]],["수요예측","채권이나 주식을 팔기 전에 기관투자자에게 얼마에 얼마나 살지 미리 물어보는 절차예요.",["2026-10-15-3"]],["단기납 종신보험","보험료를 5년, 7년처럼 짧게 내는 종신보험이에요. 납입이 끝난 뒤 환급률을 높게 설계해 저축처럼 팔리기도 했어요.",["2026-10-14-1"]],["체증형","가입 뒤 시간이 지날수록 보험금이 정해진 비율로 늘어나는 구조예요.",["2026-10-14-1"]],["납입면제","암 같은 정해진 사고가 생기면 남은 보험료를 내지 않아도 보장이 유지되는 기능이에요.",["2026-10-14-1"]],["기본자본 지급여력비율","보완자본을 빼고 기본자본만으로 계산한 지급여력비율이에요. 자본의 질을 보여줘요.",["2026-10-13-1","2026-10-05-1"]],["경영개선요구","재무 건전성이 나쁜 금융회사에 금융당국이 내리는 적기시정조치 가운데 두 번째 단계예요. 경영개선권고보다 강해요.",["2026-10-13-1"]],["완전자회사","모회사가 지분 100%를 가진 자회사예요. 상장된 회사라면 남은 주식을 모두 사들여 상장을 폐지하게 돼요.",["2026-10-13-1"]],["유상증자","회사가 새 주식을 발행해 돈을 받고 팔아 자본을 늘리는 방법이에요.",["2026-10-13-1","2026-10-01-2"]],["지수형 보험","기온, 강수량 같은 지표가 미리 정한 조건을 넘으면 손실 산정 없이 정해진 보험금을 바로 주는 보험이에요.",["2026-10-13-2"]],["실손형 보험","실제로 생긴 손실액을 계산해 그만큼(또는 비례해서) 보상하는 보험이에요.",["2026-10-13-2"]],["기저위험","지수형 보험에서 지표로 정한 보험금과 실제 손실이 서로 어긋날 위험이에요.",["2026-10-13-2"]],["풍수해보험","태풍, 홍수, 호우 같은 자연재해로 생긴 주택·상가 피해를 보상하는 정책성 보험이에요. 정부가 보험료 일부를 지원해요.",["2026-10-13-2"]],["갱신보험","일정 기간이 지나면 그때의 손해율 등을 반영해 보험료를 다시 정하는 보험이에요.",["2026-10-12-1"]],["광고 심의","보험 광고를 내기 전에 협회 등이 과장이나 누락이 없는지 미리 검토하는 절차예요.",["2026-10-12-2"]],["시정조치","규정을 어긴 광고를 지우거나 고치게 하는 조치예요. 돈으로 내는 제재는 아니에요.",["2026-10-12-2"]],["제재금","협회 자율규제에서 규정을 어긴 회사에 물리는 돈이에요.",["2026-10-12-2"]],["금융소비자보호법","금융상품을 팔 때 설명, 광고 등에서 지켜야 할 소비자 보호 규칙을 정한 법이에요.",["2026-10-12-2"]],["자율규제","법으로 정한 규제 대신 업계 협회가 스스로 기준을 만들고 심의해서 지키는 방식이에요.",["2026-10-12-2","2026-10-01-1"]],["지급보증보험","돈을 갚아야 할 사람이 못 갚을 때 보험회사가 대신 갚아주는 보험이에요. 설계사가 위촉될 때 가입하기도 해요.",["2026-10-08-1"]],["경상환자","염좌, 타박상처럼 가벼운 부상을 입은 환자예요. 자동차보험에서는 상해등급 12~14급을 말해요.",["2026-10-08-2","2022-12-28-b1"]],["상해등급","자동차사고 부상의 정도를 1급(가장 무거움)부터 14급까지 나눈 기준이에요.",["2026-10-08-2"]],["지급보증","보험사가 병원에 '이 환자의 치료비는 우리가 내겠다'고 약속하는 것이에요.",["2026-10-08-2"]],["향후치료비","합의할 때 앞으로 받을 치료에 쓸 돈이라며 미리 주는 보험금이에요.",["2026-10-08-2"]],["신종자본증권","만기가 아주 길고 이자 지급을 미룰 수 있어서 채권이지만 자본에 가깝게 인정받는 증권이에요.",["2026-10-08-3"]],["가용자본","보험사가 손실을 메우는 데 실제로 쓸 수 있는 자본이에요. 지급여력비율의 분자예요.",["2026-10-08-3","2022-12-05-b1"]],["투자설명회","증권을 팔기 전에 투자자들을 만나 회사와 발행 조건을 설명하는 자리예요.",["2026-10-08-3"]],["수용률","신청한 건 가운데 실제로 인정받은 건의 비율이에요.",["2026-10-06-1"]],["상품위원회","생명·손해보험협회에 있는 심의 기구로, 배타적사용권 신청 상품의 독창성 등을 심사해요.",["2026-10-06-1"]],["경과조치","새 규제를 바로 다 적용하지 않고 정해진 기간 동안 단계적으로 맞추도록 시간을 주는 장치예요.",["2026-10-05-1"]],["공개매각","정해진 상대와만 협상하는 수의계약과 달리, 매각 공고를 내고 여러 인수 후보의 제안을 받아 파는 방식이에요.",["2026-10-05-1"]],["보험계약부채","보험사가 앞으로 가입자에게 줄 보험금과 비용을 지금 가치로 계산해 장부에 올린 빚이에요. 최선추정부채, 위험조정, 보험계약마진으로 이뤄져요.",["2026-10-04-1"]],["할인율","미래에 오갈 돈을 지금 가치로 바꿀 때 쓰는 이자율이에요. 할인율이 오르면 같은 미래 금액의 현재가치가 작아져요.",["2026-10-04-1"]],["유동성프리미엄","보험부채처럼 중간에 쉽게 팔 수 없는 성격을 반영해 무위험금리에 더해 주는 추가 금리예요.",["2026-10-04-1"]],["기타포괄손익","채권 평가손익처럼 당기순이익에는 넣지 않고 자본에 바로 반영하는 손익이에요.",["2026-10-04-1"]],["불완전판매비율","판매한 계약 가운데 설명 부족이나 잘못된 안내로 계약이 취소되거나 민원이 생긴 계약의 비율이에요.",["2026-10-01-1"]],["13회차 유지율","가입한 계약 가운데 13번째 보험료까지 내며 1년 넘게 유지되는 계약의 비율이에요. 판매 품질을 보는 대표 지표예요.",["2026-10-01-1"]],["준법감시인","회사가 법과 내부 규정을 잘 지키는지 감시하는 책임자예요.",["2026-10-01-1"]],["여신전문금융업","예금은 받지 않고 대출, 리스, 할부금융 같은 돈 빌려주는 일을 전문으로 하는 금융업이에요. 캐피탈사와 카드사가 대표적이에요.",["2026-10-01-2"]],["손자회사","자회사가 지분을 가진 회사예요. 한화생명의 자회사가 될 애큐온캐피탈이 애큐온저축은행을 100% 가지고 있어서 손자회사가 돼요.",["2026-10-01-2"]],["종합금융투자사업자","자기자본이 일정 규모를 넘는 대형 증권사에 기업 대출과 투자 업무를 더 넓게 허용하는 제도예요.",["2026-10-01-2"]],["대주주 변경 승인","금융회사의 최대주주가 바뀔 때 금융당국이 새 주인의 자격을 심사해 허락하는 절차예요.",["2026-10-01-2"]],["선택형 할인특약","1·2세대 계약은 유지하면서 일부 비급여 보장을 빼거나 자기부담을 높이는 대신 보험료를 할인받는 특약이에요.",["2026-05-05-b1"]],["사고내용 조작","실제 사고는 있었지만 진단서나 진료기록을 위·변조해 피해를 부풀리는 보험사기 유형이에요.",["2026-03-31-b1"]],["사업비율","받은 보험료 가운데 보험을 운영하는 데 쓴 비용(사업비)의 비율이에요.",["2026-03-25-b1"]],["풍선효과","한 곳을 규제하면 문제가 다른 곳으로 옮겨 가 부풀어 오르는 현상이에요.",["2026-03-11-b1"]],["손익분기선","이익도 손실도 나지 않는 경계예요. 자동차보험은 손해율 약 80%를 업계 손익분기선으로 봐요.",["2026-01-13-b1"]],["시니어타운","노년층이 생활하도록 주거와 돌봄, 편의 서비스를 함께 제공하는 주거 시설이에요.",["2025-12-15-b1"]],["알선·유인","다른 사람이 보험사기에 가담하도록 연결해주거나 꾀어내는 행위예요.",["2025-10-29-b1","2024-08-13-b1"]],["할증","사고 이력 등으로 보험료를 원래보다 더 올려 받는 것이에요.",["2025-10-29-b1","2024-08-13-b1"]],["톤틴보험","가입자가 오래 살수록 더 많은 보험금을 연금 형태로 받는 상품이에요.",["2025-10-22-b1"]],["예정이율","보험사가 받은 보험료를 굴려서 얻을 것으로 미리 정한 수익률이에요. 낮아질수록 같은 보장에 보험료가 비싸져요.",["2025-10-22-b1","2025-07-29-b1","2024-10-14-b1"]],["공시이율","저축성·연금보험 적립금에 붙는 이율로, 시장금리에 맞춰 보험사가 매달 정해요.",["2025-07-29-b1"]],["역마진","보험사가 가입자에게 약속한 이율보다 실제로 굴려서 버는 수익률이 낮아 손해를 보는 상태예요.",["2025-07-29-b1","2022-11-07-b1"]],["스트레스 테스트","금리 급변 같은 극단적인 상황을 가정해 회사가 얼마나 버티는지 미리 계산해보는 점검이에요.",["2025-06-11-b1"]],["유지관리 수수료","계약이 유지되는 동안 설계사에게 나눠 주는 수수료예요. 계약을 오래 지킬수록 더 받아요.",["2025-06-01-b1"]],["계약 재매입","보험사가 일정한 보상을 하고 가입자의 기존 계약을 해지하는 방식이에요. 실손에서는 가입자가 원할 때만 하기로 했어요.",["2025-04-01-b1"]],["보상한도","보험사가 정해진 기간에 보상해주는 최대 금액이에요.",["2025-04-01-b1"]],["상생금융","금융회사가 소비자 부담을 덜기 위해 금리나 보험료를 낮추는 등 이익을 나누는 활동이에요.",["2025-01-22-b1"]],["의무보험","법으로 가입이 정해진 보험이에요. 자동차보험의 책임보험이 대표적이에요.",["2025-01-22-b1"]],["간병보험","입원이나 요양 중 간병인을 쓸 때 드는 비용을 보장하는 보험이에요.",["2024-11-28-b1"]],["약관","보험사가 보험금을 언제, 얼마나 줄지 등 계약 내용을 미리 정해 둔 문서예요.",["2024-11-28-b1"]],["무·저해지보험","중간에 해지하면 돌려받는 돈이 없거나 적은 대신 보험료가 싼 보험이에요.",["2024-11-11-b1","2023-05-31-b1"]],["완납","정해진 보험료 납입 기간을 다 채워 보험료를 모두 낸 상태예요.",["2024-11-11-b1"]],["원칙모형","당국이 정한 기본 계산 방식이에요. 무·저해지보험에서는 완납 시점 해지율이 0%로 수렴하도록 해요.",["2024-11-11-b1"]],["새 국제회계기준","2023년부터 보험사가 쓰는 회계기준이에요. 보험부채를 지금 시점의 가치로 다시 평가해요.",["2024-03-26-b1","2022-12-29-b1"]],["보장성 보험","사고나 질병 같은 위험이 생겼을 때 보험금을 주는 보험이에요. 만기에 돈을 돌려받는 저축성 보험과 구분해요.",["2024-03-26-b1"]],["시가평가","자산이나 부채를 처음 거래한 가격이 아니라 지금 시점의 가치로 평가하는 방식이에요.",["2022-12-29-b1"]],["발생주의","돈이 들어온 때가 아니라 서비스를 제공한 때에 맞춰 수익을 인식하는 방식이에요.",["2022-12-29-b1"]],["조건부자본증권","보험사가 어려워지면 원금이 깎이거나 주식으로 바뀌는 조건이 붙은 채권이에요. 자본을 늘리는 수단으로 써요.",["2022-12-29-b1"]],["선임계리사","보험사의 책임준비금과 계리가정이 적정한지 검증하고 확인하는 책임을 지는 계리사예요.",["2022-12-29-b1"]],["과실책임주의","사고에서 잘못한 비율(과실)만큼 각자 비용을 부담하는 원칙이에요.",["2022-12-28-b1"]],["과잉진료","부상 정도에 비해 지나치게 오래 또는 많이 받는 치료예요. 보험금이 새는 원인이 돼요.",["2022-12-28-b1"]],["요구자본","큰 충격이 와도 버티려면 갖고 있어야 하는 자본의 양이에요. 지급여력비율의 분모예요.",["2022-12-05-b1"]],["저축성보험","보장보다 목돈 마련이 주된 목적인 보험이에요. 만기에 낸 보험료와 이자를 합쳐 돌려받아요.",["2022-11-07-b1"]],["전속 설계사","한 보험사에 소속돼 그 회사 상품만 파는 설계사예요.",["2021-04-29-b1"]],["보험료 차등제","가입자의 보험금 이용 실적에 따라 보험료를 할인하거나 할증하는 제도예요.",["2020-12-09-b1"]],["산정특례","암 같은 중증질환자의 건강보험 본인부담을 크게 낮춰주는 제도예요.",["2020-12-09-b1"]]];
